import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum SupplierStatus {
  POTENTIAL = '潜在',
  VERIFIED = '已准入',
  QUALIFIED = '合格',
  BLACKLISTED = '黑名单'
}

export enum ProcurementMethod {
  INQUIRY = '询比价',
  BIDDING = '竞价',
  MALL = '商城直采'
}

export enum ApprovalStatus {
  DRAFT = '草稿',
  PENDING = '审批中',
  APPROVED = '已通过',
  REJECTED = '已驳回'
}

export interface Supplier {
  id: string;
  name: string;
  category: string;
  creditScore: number;
  status: SupplierStatus;
  location: string;
  tags: string[];
}

export interface ProcurementProject {
  id: string;
  title: string;
  budget: number;
  method: ProcurementMethod;
  status: ApprovalStatus;
  createTime: string;
}

export interface AnalyticsMetric {
  name: string;
  value: number;
  trend: number;
  unit: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSupplierRisk = async (supplierName: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `请分析供应商 "${supplierName}" 的潜在经营风险、行业口碑和背景。请以专业采购经理的角度提供建议。`,
  });
  return response.text;
};

export const suggestSourcingStrategy = async (itemCategory: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `针对 "${itemCategory}" 类别物资，请建议最佳的采购寻源策略（询价、竞价或商城）并给出理由。`,
  });
  return response.text;
};

export const generateProcurementReport = async (data: any) => {
