                <div>
                  <div className="flex items-center gap-3">
                    <span className="text-xs font-mono text-slate-400">{p.id}</span>
                    <span className={`flex items-center gap-1 text-xs font-bold px-2 py-0.5 rounded-full ${p.status === ApprovalStatus.APPROVED ? 'bg-green-50 text-green-600' : 'bg-slate-50 text-slate-500'}`}>
                      {getStatusIcon(p.status)} {p.status}
                    </span>
                  </div>
                  <h3 className="text-lg font-bold text-slate-900 mt-1">{p.title}</h3>
                  <div className="flex gap-4 mt-2 text-sm text-slate-500">
