};

export default ProcurementExecution;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import SupplierManagement from './pages/SupplierManagement';
import ProcurementExecution from './pages/ProcurementExecution';
import ContractManagement from './pages/ContractManagement';
import Analytics from './pages/Analytics';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'suppliers':
        return <SupplierManagement />;
      case 'procurement':
        return <ProcurementExecution />;
      case 'contracts':
        return <ContractManagement />;
      case 'analytics':
        return <Analytics />;
      default:
        return (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
            <p className="text-lg">功能模块正在开发中...</p>
          </div>
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface SourcingResult {
  suppliers: {
    name: string;
    creditRating: string;
    matchScore: number;
    platform: string;
    advantage: string;
    potentialRisk: string;
  }[];
  strategicAdvice: string;
}

export const smartSourcingAssistant = async (category: string): Promise<SourcingResult> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `作为一名资深采购专家，请针对"${category}"这类物资进行智能寻源分析。
    请模拟从1688、企查查、天眼查等平台聚合数据，推荐3-4家具有代表性的供应商（可以包含真实存在的行业巨头或典型的优质中小企业），并给出信用评级、匹配度、核心优势及潜在风险。
    最后提供一段针对该品类的寻源策略建议。`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          suppliers: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING, description: "供应商全称" },
                creditRating: { type: Type.STRING, description: "信用评级，如 AAA, AA, A" },
                matchScore: { type: Type.NUMBER, description: "匹配度百分比，0-100" },
                platform: { type: Type.STRING, description: "主要数据来源平台" },
                advantage: { type: Type.STRING, description: "核心竞争优势" },
                potentialRisk: { type: Type.STRING, description: "需要关注的潜在风险" }
              },
              required: ["name", "creditRating", "matchScore", "platform", "advantage", "potentialRisk"]
            }
          },
          strategicAdvice: { type: Type.STRING, description: "专业的寻源策略建议" }
        },
        required: ["suppliers", "strategicAdvice"]
      }
    },
  });

  try {
    return JSON.parse(response.text || '{}') as SourcingResult;
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    throw new Error("寻源分析失败，请稍后重试。");
  }
};

