                <p className="text-xs font-medium max-w-[200px] leading-relaxed">请从左侧列表选择一项供应商入驻申请，AI 将为您同步提供深度合规分析报告。</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default SupplierManagement;

import React, { useState, useEffect } from 'react';
import { 
  ShoppingCart, FilePlus, Gavel, Search, CheckCircle2, Clock, 
  AlertCircle, ShoppingBag, Plus, Filter, ArrowRight, UserCheck, 
  FileText, TrendingDown, DollarSign, Package, Eye, ChevronRight,
  Sparkles, Loader2, X, Send
} from 'lucide-react';
import { ProcurementMethod, ApprovalStatus } from '../types';
import { evaluateQuotations } from '../services/geminiService';

interface ProcurementExecutionProps {
  initialTab?: string;
}

// Extended Project Interface for local state
interface Project {
  id: string;
  title: string;
  method: ProcurementMethod;
  status: ApprovalStatus;
  budget: number;
  deadline: string;
  createTime: string;
  quotesCount: number;
  // Mocking workflow logs and quotes locally
  workflow?: { step: string; user: string; time: string; status: 'done' | 'active' | 'pending' }[];
  quotes?: { supplier: string; price: number; delivery: string; quality: string; advantage: string }[];
}

const ProcurementExecution: React.FC<ProcurementExecutionProps> = ({ initialTab = 'projects' }) => {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isQuoteModalOpen, setIsQuoteModalOpen] = useState(false);

  // Form States
  const [newProjectForm, setNewProjectForm] = useState({
    title: '',
    budget: '',
    deadline: '',
    method: ProcurementMethod.INQUIRY
  });

  const [newQuoteForm, setNewQuoteForm] = useState({
    supplier: '',
    price: '',
    delivery: '',
    advantage: ''
  });

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab]);

  // Mock Initial Data
  const [projects, setProjects] = useState<Project[]>([
    { 
      id: 'PR-2023001', 
      title: '2023年Q4办公室物料集中采购', 
      method: ProcurementMethod.INQUIRY, 
      status: ApprovalStatus.APPROVED, 
      budget: 150000, 
      deadline: '2023-11-30', 
      createTime: '2023-10-15', 
      quotesCount: 3,
      quotes: [
        { supplier: '晨光科力普', price: 142000, delivery: '3天', quality: '优', advantage: '长期合作伙伴，售后无忧' },
        { supplier: '齐心文具', price: 138000, delivery: '5天', quality: '良', advantage: '价格最低，库存充足' },
        { supplier: '办公伙伴', price: 145000, delivery: '2天', quality: '优', advantage: '送货上门，响应最快' },
      ]
    },
    { 
      id: 'PR-2023002', 
      title: '服务器扩容硬件招标项目', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.PENDING, 
      budget: 850000, 
      deadline: '2023-11-15', 
      createTime: '2023-10-20', 
      quotesCount: 0,
      quotes: []
    },
    { 
      id: 'PR-2023003', 
      title: '营销中心礼品定制(竞价)', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.DRAFT, 
      budget: 50000, 
      deadline: '2023-10-25', 
      createTime: '2023-10-22', 
      quotesCount: 0,
      quotes: []
    },
  ]);

  // --- Actions ---

  const handleCreateProject = () => {
    if (!newProjectForm.title || !newProjectForm.budget) return;

    const newProject: Project = {
      id: `PR-${new Date().getFullYear()}${String(projects.length + 1).padStart(3, '0')}`,
      title: newProjectForm.title,
      method: newProjectForm.method,
      status: ApprovalStatus.DRAFT,
      budget: Number(newProjectForm.budget),
      deadline: newProjectForm.deadline,
      createTime: new Date().toISOString().split('T')[0],
      quotesCount: 0,
      quotes: []
    };

    setProjects([newProject, ...projects]);
    setIsCreateModalOpen(false);
    setNewProjectForm({ title: '', budget: '', deadline: '', method: ProcurementMethod.INQUIRY });
    alert('项目创建成功！当前状态：草稿');
  };

  const handleSubmitForApproval = (project: Project) => {
    const updated = projects.map(p => p.id === project.id ? { ...p, status: ApprovalStatus.PENDING } : p);
    setProjects(updated);
    if (selectedProject?.id === project.id) setSelectedProject({ ...project, status: ApprovalStatus.PENDING });
    alert('已提交审批流程，等待管理层审核。');
  };

  const handleApproveProject = (project: Project) => {
    const updated = projects.map(p => p.id === project.id ? { ...p, status: ApprovalStatus.APPROVED } : p);
    setProjects(updated);
    if (selectedProject?.id === project.id) setSelectedProject({ ...project, status: ApprovalStatus.APPROVED });
    alert('审批通过！项目已立项，可以开始邀请供应商报价。');
  };

  const handleRejectProject = (project: Project) => {
    const updated = projects.map(p => p.id === project.id ? { ...p, status: ApprovalStatus.REJECTED } : p);
    setProjects(updated);
    if (selectedProject?.id === project.id) setSelectedProject({ ...project, status: ApprovalStatus.REJECTED });
  };

  const handleAddQuote = () => {
    if (!selectedProject) return;
    const newQuote = {
      supplier: newQuoteForm.supplier,
      price: Number(newQuoteForm.price),
      delivery: newQuoteForm.delivery,
      quality: '未知',
      advantage: newQuoteForm.advantage
    };

    const updatedProject = {
      ...selectedProject,
      quotesCount: (selectedProject.quotesCount || 0) + 1,
      quotes: [...(selectedProject.quotes || []), newQuote]
    };

    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
    setIsQuoteModalOpen(false);
    setNewQuoteForm({ supplier: '', price: '', delivery: '', advantage: '' });
  };

  const handleGeneratePO = () => {
    alert(`采购订单 (PO) 已生成！\n\n项目：${selectedProject?.title}\n状态：已推送至供应商协同端`);
  };

  const handleOpenProject = async (project: Project) => {
    setSelectedProject(project);
    // Auto evaluate only if approved and has quotes
    if (project.status === ApprovalStatus.APPROVED && (project.quotes?.length || 0) > 0) {
      setIsEvaluating(true);
      setAiAnalysis(null);
      try {
        const analysis = await evaluateQuotations(project.title, project.quotes || []);
        setAiAnalysis(analysis);
      } catch (err) {
        setAiAnalysis("无法生成AI评估报告。");
      } finally {
        setIsEvaluating(false);
      }
    } else {
      setAiAnalysis(null);
    }
  };

  const getStatusIcon = (status: ApprovalStatus) => {
    switch(status) {
      case ApprovalStatus.APPROVED: return <CheckCircle2 size={16} className="text-green-500" />;
      case ApprovalStatus.PENDING: return <Clock size={16} className="text-blue-500" />;
      case ApprovalStatus.REJECTED: return <AlertCircle size={16} className="text-red-500" />;
      case ApprovalStatus.DRAFT: return <FileText size={16} className="text-slate-400" />;
      default: return <FileText size={16} className="text-slate-400" />;
    }
  };

  const getStatusBadgeClass = (status: ApprovalStatus) => {
    switch(status) {
      case ApprovalStatus.APPROVED: return 'bg-green-50 text-green-700 border-green-100';
      case ApprovalStatus.PENDING: return 'bg-blue-50 text-blue-700 border-blue-100';
      case ApprovalStatus.REJECTED: return 'bg-red-50 text-red-700 border-red-100';
      case ApprovalStatus.DRAFT: return 'bg-slate-100 text-slate-600 border-slate-200';
      default: return 'bg-slate-50 text-slate-600 border-slate-100';
    }
  };

  // --- Renders ---

  if (selectedProject) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-4">
            <button onClick={() => setSelectedProject(null)} className="p-2 hover:bg-slate-100 rounded-xl transition-colors">
              <ChevronRight className="rotate-180" size={24} />
            </button>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-bold text-slate-900">{selectedProject.title}</h1>
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold border ${getStatusBadgeClass(selectedProject.status)}`}>
                  {selectedProject.status}
                </span>
              </div>
              <p className="text-sm text-slate-500 mt-1">项目编号：{selectedProject.id} · 方式：{selectedProject.method}</p>
            </div>
          </div>
          <div className="flex gap-3">
            {selectedProject.status === ApprovalStatus.DRAFT && (
               <button 
                 onClick={() => handleSubmitForApproval(selectedProject)}
                 className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 flex items-center gap-2"
               >
                 <Send size={18} /> 提交审批
               </button>
            )}

            {selectedProject.status === ApprovalStatus.PENDING && (
               <div className="flex gap-2">
                 <button 
                   onClick={() => handleRejectProject(selectedProject)}
                   className="px-4 py-2 border border-red-200 text-red-600 rounded-xl font-bold hover:bg-red-50"
                 >
                   驳回
                 </button>
                 <button 
                   onClick={() => handleApproveProject(selectedProject)}
                   className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 shadow-lg shadow-green-200 flex items-center gap-2"
                 >
                   <CheckCircle2 size={18} /> 通过审批
                 </button>
               </div>
            )}

            {selectedProject.status === ApprovalStatus.APPROVED && (
              <>
                <button 
                  onClick={() => setIsQuoteModalOpen(true)}
                  className="px-4 py-2 border border-slate-200 rounded-xl font-bold text-slate-600 hover:bg-slate-50 flex items-center gap-2"
                >
                  <Plus size={18} /> 录入报价
                </button>
                <button 
                  onClick={handleGeneratePO}
                  className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200"
                >
                  生成采购订单 (PO)
                </button>
              </>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="flex items-center justify-between p-4 pt-0 border-b border-slate-100 mb-4">
                <h3 className="font-black text-slate-900 flex items-center gap-2">
                  <Package size={20} className="text-blue-600" />
                  询价/竞价明细
                </h3>
                <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded">
                  共收到 {selectedProject.quotesCount} 份报价
                </span>
              </div>

              <div className="overflow-x-auto p-4 pt-0">
                <table className="w-full text-sm">
                  <thead className="bg-slate-50 text-slate-500 border-b border-slate-100">
                    <tr>
                      <th className="px-4 py-3 text-left font-bold">供应商</th>
                      <th className="px-4 py-3 text-left font-bold">报价总额</th>
