                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {(selectedProject.quotes || []).map((q, i) => (
                      <tr key={i} className="hover:bg-slate-50 transition-colors">
                        <td className="px-4 py-4 font-bold text-slate-900">{q.supplier}</td>
