                        <td className="px-4 py-4 text-slate-500 text-xs font-medium">{q.advantage}</td>
                        <td className="px-4 py-4 text-center">
                          <button className="text-blue-600 font-bold hover:underline">设为预选</button>
                        </td>
                      </tr>
                    ))}
                    {(selectedProject.quotes || []).length === 0 && (
                      <tr>
                        <td colSpan={5} className="py-10 text-center text-slate-400">
                          <div className="flex flex-col items-center gap-2">
                             <ShoppingBag className="opacity-20" size={32} />
                             <p>暂无报价数据，请邀请供应商报价或手动录入</p>
                          </div>
                        </td>
                      </tr>
