                  </tbody>
                </table>
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
              <h3 className="font-black text-slate-900 mb-6 flex items-center gap-2">
                <UserCheck size={20} className="text-green-600" />
                项目全生命周期追踪
              </h3>
              <div className="relative pl-8 space-y-8">
                <div className="absolute left-3.5 top-2 bottom-2 w-px bg-slate-100"></div>
                {[
                  { step: '发起立项申请', user: '系统管理员', time: selectedProject.createTime, status: 'done' },
                  { step: '部门经理审核', user: '王建国', time: '---', status: selectedProject.status !== ApprovalStatus.DRAFT ? 'done' : 'pending' },
                  { step: '采购中心决标', user: '您', time: '---', status: selectedProject.status === ApprovalStatus.APPROVED ? 'active' : 'pending' },
                ].map((s, i) => (
                  <div key={i} className="relative">
                    <div className={`absolute -left-6 top-1.5 w-3 h-3 rounded-full border-2 border-white shadow-sm ${s.status === 'done' ? 'bg-green-500' : s.status === 'active' ? 'bg-blue-600 animate-pulse' : 'bg-slate-300'}`}></div>
