                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">报价总额 (元)</label>
                        <input type="number" value={newQuoteForm.price} onChange={e => setNewQuoteForm({...newQuoteForm, price: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500" />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-1">承诺交期</label>
                        <input type="text" placeholder="如: 3天" value={newQuoteForm.delivery} onChange={e => setNewQuoteForm({...newQuoteForm, delivery: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500" />
                    </div>
                 </div>
                 <div>
                    <label className="block text-sm font-bold text-slate-700 mb-1">核心优势/备注</label>
                    <textarea value={newQuoteForm.advantage} onChange={e => setNewQuoteForm({...newQuoteForm, advantage: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500 h-24"></textarea>
                 </div>
                 <button onClick={handleAddQuote} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg mt-2">确认录入</button>
               </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- Main List View ---

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
