                    <h3 className="text-lg font-black text-slate-900 mt-2 group-hover:text-blue-600 transition-colors tracking-tight">{p.title}</h3>
                    <div className="flex gap-8 mt-3 text-[11px] font-black uppercase text-slate-500 tracking-tighter">
                      <span className="flex items-center gap-1.5"><DollarSign size={14} className="text-slate-300" /> 预算: <b className="text-slate-900">¥{(p.budget/10000).toFixed(1)}w</b></span>
                      <span className="flex items-center gap-1.5"><Clock size={14} className="text-slate-300" /> 截止: <b className="text-slate-900">{p.deadline}</b></span>
                      <span className="flex items-center gap-1.5"><Package size={14} className="text-slate-300" /> 报价数: <b className="text-blue-600">{p.quotesCount}</b></span>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-6">
                  <div className="text-right hidden sm:block">
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Created At</p>
                    <p className="text-xs font-black text-slate-700">{p.createTime}</p>
                  </div>
                  <ChevronRight size={28} className="text-slate-200 group-hover:text-blue-600 group-hover:translate-x-1 transition-all" />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'approval' && (
         <div className="space-y-4 animate-in fade-in duration-300">
            <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-center gap-3 text-blue-800">
              <UserCheck size={20} />
              <span className="text-sm font-bold">待审批任务 ({projects.filter(p => p.status === ApprovalStatus.PENDING).length})</span>
            </div>
            {projects.filter(p => p.status === ApprovalStatus.PENDING).map(p => (
              <div key={p.id} className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
                 <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center font-bold">审</div>
                    <div>
                       <h4 className="font-bold text-slate-900">{p.title}</h4>
                       <p className="text-xs text-slate-500 mt-1">申请人: 张三 · 预算: ¥{p.budget}</p>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => handleOpenProject(p)} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-50 rounded-lg">查看详情</button>
                    <button onClick={() => handleApproveProject(p)} className="px-4 py-2 text-sm font-bold text-white bg-green-600 hover:bg-green-700 rounded-lg shadow-md">通过</button>
                 </div>
              </div>
            ))}
            {projects.filter(p => p.status === ApprovalStatus.PENDING).length === 0 && (
               <div className="py-20 text-center text-slate-400">
                  <CheckCircle2 size={48} className="mx-auto opacity-20 mb-4" />
                  <p>当前没有待审批的采购项目</p>
               </div>
            )}
         </div>
      )}

      {activeTab === 'mall' && (
        <div className="bg-white p-12 rounded-[2.5rem] border border-slate-200 shadow-sm text-center relative overflow-hidden">
            <div className="max-w-2xl mx-auto py-16 relative z-10">
                <div className="w-24 h-24 bg-blue-600 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-blue-200 rotate-3">
                  <ShoppingCart size={48} className="text-white" />
                </div>
                <h2 className="text-4xl font-black text-slate-900 tracking-tighter">企业 B2B 集采商城</h2>
                <p className="text-slate-500 mt-4 mb-10 text-lg font-medium leading-relaxed">基于智能 RPA 技术，实时同步京东企业购、苏宁 B2B、震坤行等平台的 API 价格，确保企业享受同款全网最低协议价。</p>
                <div className="flex gap-3 bg-slate-50 p-2 rounded-[2rem] border border-slate-200 shadow-inner">
                    <input type="text" placeholder="搜索全网商品型号、SKU、条码或直接粘贴商城链接..." className="flex-1 px-6 py-4 bg-transparent outline-none font-bold text-slate-900" />
                    <button className="bg-slate-900 text-white px-10 py-4 rounded-[1.5rem] font-black hover:bg-black transition-all shadow-xl">智能比价</button>
                </div>
                <div className="mt-16 grid grid-cols-4 gap-12 opacity-30 grayscale hover:grayscale-0 transition-all cursor-default">
                    <div className="flex items-center justify-center font-black italic text-slate-800 text-2xl">JD.COM</div>
                    <div className="flex items-center justify-center font-black italic text-slate-800 text-2xl">SUNING</div>
                    <div className="flex items-center justify-center font-black italic text-slate-800 text-2xl">ZKH</div>
                    <div className="flex items-center justify-center font-black italic text-slate-800 text-2xl">VIP.COM</div>
                </div>
            </div>
        </div>
      )}

      {/* Create Project Modal */}
      {isCreateModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
           <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg p-8 animate-in zoom-in-95 duration-200">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-slate-900">创建新采购立项</h3>
                <button onClick={() => setIsCreateModalOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={20} /></button>
              </div>

              <div className="space-y-4">
                 <div>
                    <label className="block text-sm font-bold text-slate-700 mb-1">项目标题</label>
                    <input 
                      type="text" 
                      placeholder="例如: 2024年度IT设备集中采购" 
                      value={newProjectForm.title}
                      onChange={(e) => setNewProjectForm({...newProjectForm, title: e.target.value})}
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500" 
                    />
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div>
                       <label className="block text-sm font-bold text-slate-700 mb-1">采购预算 (元)</label>
                       <input 
                         type="number" 
                         value={newProjectForm.budget}
                         onChange={(e) => setNewProjectForm({...newProjectForm, budget: e.target.value})}
                         className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                    <div>
                       <label className="block text-sm font-bold text-slate-700 mb-1">截止日期</label>
                       <input 
                         type="date" 
                         value={newProjectForm.deadline}
                         onChange={(e) => setNewProjectForm({...newProjectForm, deadline: e.target.value})}
                         className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2">采购方式</label>
                    <div className="flex gap-4">
                       <label className="flex items-center gap-2 cursor-pointer p-3 border border-slate-200 rounded-xl flex-1 hover:bg-slate-50 has-[:checked]:border-blue-500 has-[:checked]:bg-blue-50">
                          <input 
                            type="radio" 
                            name="method" 
                            checked={newProjectForm.method === ProcurementMethod.INQUIRY}
                            onChange={() => setNewProjectForm({...newProjectForm, method: ProcurementMethod.INQUIRY})}
                            className="hidden"
                          />
                          <div className={`w-4 h-4 rounded-full border-2 ${newProjectForm.method === ProcurementMethod.INQUIRY ? 'border-blue-500 bg-blue-500' : 'border-slate-300'}`}></div>
                          <span className="text-sm font-bold">询比价 (Inquiry)</span>
                       </label>
                       <label className="flex items-center gap-2 cursor-pointer p-3 border border-slate-200 rounded-xl flex-1 hover:bg-slate-50 has-[:checked]:border-blue-500 has-[:checked]:bg-blue-50">
                          <input 
                            type="radio" 
                            name="method" 
                            checked={newProjectForm.method === ProcurementMethod.BIDDING}
                            onChange={() => setNewProjectForm({...newProjectForm, method: ProcurementMethod.BIDDING})}
                            className="hidden"
                          />
                          <div className={`w-4 h-4 rounded-full border-2 ${newProjectForm.method === ProcurementMethod.BIDDING ? 'border-blue-500 bg-blue-500' : 'border-slate-300'}`}></div>
                          <span className="text-sm font-bold">公开竞价 (Bidding)</span>
                       </label>
                    </div>
                 </div>

                 <button 
                   onClick={handleCreateProject}
                   className="w-full py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 shadow-lg mt-4"
                 >
                   立即创建
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default ProcurementExecution;

