      budget: Number(newProjectForm.budget),
      deadline: newProjectForm.deadline,
      createTime: new Date().toISOString().split('T')[0],
      quotesCount: 0,
      quotes: [],
      // Conditional Config
      bidConfig: isBidding ? {
        startPrice: Number(newProjectForm.startPrice || newProjectForm.budget),
        minStep: Number(newProjectForm.minStep),
        duration: Number(newProjectForm.duration),
        extensionRule: 2
      } : undefined,
      inquiryConfig: !isBidding ? {
        inviteCount: Number(newProjectForm.inviteCount),
        round: 1
      } : undefined
    };

    setProjects([newProject, ...projects]);
    setIsCreateModalOpen(false);
    // Reset form...
    alert('项目创建成功！当前状态：草稿');
  };

  const handleSubmitForApproval = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.PENDING);
    alert('已提交审批流程，等待管理层审核。');
  };

  const handleApproveProject = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.APPROVED);
    alert('审批通过！项目已立项，可以开始邀请供应商报价。');
  };

  const handleRejectProject = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.REJECTED);
  };

  const updateProjectStatus = (id: string, status: ApprovalStatus) => {
    const updated = projects.map(p => p.id === id ? { ...p, status } : p);
    setProjects(updated);
    if (selectedProject?.id === id) setSelectedProject({ ...selectedProject!, status });
  };

  const handleAddQuote = () => {
    if (!selectedProject) return;
    const newQuote: Quote = {
      supplier: newQuoteForm.supplier,
      price: Number(newQuoteForm.price),
      delivery: newQuoteForm.delivery,
      quality: '未知',
      advantage: newQuoteForm.advantage,
      paymentTerms: '月结30天' 
    };

    // If bidding, calculate rank
    let updatedQuotes = [...(selectedProject.quotes || []), newQuote];
    if (selectedProject.method === ProcurementMethod.BIDDING) {
      updatedQuotes.sort((a, b) => a.price - b.price);
      updatedQuotes = updatedQuotes.map((q, idx) => ({ ...q, rank: idx + 1 }));
    }

    const updatedProject = {
      ...selectedProject,
      quotesCount: updatedQuotes.length,
      quotes: updatedQuotes
    };

    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
    setIsQuoteModalOpen(false);
    setNewQuoteForm({ supplier: '', price: '', delivery: '', advantage: '' });
  };

  const handleGeneratePO = () => {
    const winner = selectedProject?.quotes?.find(q => q.isWinner) || selectedProject?.quotes?.[0]; // Default to first if none selected
    alert(`采购订单 (PO) 已生成！\n\n项目：${selectedProject?.title}\n供应商：${winner?.supplier}\n金额：¥${winner?.price}\n状态：已推送至供应商协同端`);
  };

  const handleAwardSupplier = (supplierName: string) => {
    if (!selectedProject) return;
    const updatedQuotes = selectedProject.quotes?.map(q => ({
        ...q,
        isWinner: q.supplier === supplierName
    }));
    const updatedProject = { ...selectedProject, quotes: updatedQuotes };
    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
  };

  const handleOpenProject = async (project: Project) => {
    setSelectedProject(project);
    // Determine AI context based on method
    if (project.status === ApprovalStatus.APPROVED && (project.quotes?.length || 0) > 0) {
      // Only auto-analyze for inquiry, Bidding needs manual trigger or end of auction
      if (project.method === ProcurementMethod.INQUIRY) {
        setIsEvaluating(true);
        try {
          const analysis = await evaluateQuotations(project.title, project.quotes || []);
          setAiAnalysis(analysis);
        } catch (err) {
          setAiAnalysis(null);
        } finally {
          setIsEvaluating(false);
        }
      }
    } else {
      setAiAnalysis(null);
    }
  };

  // --- Render Helpers ---

  const renderInquiryView = () => (
