      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="flex items-center justify-between p-4 pt-0 border-b border-slate-100 mb-4">
          <div>
            <h3 className="font-black text-slate-900 flex items-center gap-2">
              <Scale size={20} className="text-blue-600" />
              综合比价单 (Comparison Sheet)
            </h3>
            <p className="text-xs text-slate-500 mt-1">
              第 <b className="text-slate-900">{selectedProject?.inquiryConfig?.round}</b> 轮报价 · 
              应邀 {selectedProject?.inquiryConfig?.inviteCount} 家 · 
              实回 {selectedProject?.quotesCount} 家
            </p>
          </div>
          <button className="text-sm font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition-colors">
            发起新一轮议价
          </button>
        </div>

        <div className="overflow-x-auto p-4 pt-0">
