                <th className="px-4 py-3 text-left font-bold">账期条款</th>
                <th className="px-4 py-3 text-left font-bold">交货期</th>
                <th className="px-4 py-3 text-left font-bold w-1/3">核心优势/备注</th>
                <th className="px-4 py-3 text-center font-bold">决标</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {(selectedProject?.quotes || []).map((q, i) => (
                <tr key={i} className={`hover:bg-slate-50 transition-colors ${q.isWinner ? 'bg-green-50/50' : ''}`}>
                  <td className="px-4 py-4 font-bold text-slate-900 flex items-center gap-2">
                    {q.isWinner && <CheckCircle2 size={16} className="text-green-600" />}
                    {q.supplier}
                  </td>
                  <td className="px-4 py-4">
                    <span className="text-blue-600 font-bold">¥{q.price.toLocaleString()}</span>
