                  <td className="px-4 py-4 text-slate-600 font-medium">{q.paymentTerms}</td>
                  <td className="px-4 py-4 text-slate-600">{q.delivery}</td>
                  <td className="px-4 py-4 text-slate-500 text-xs font-medium leading-relaxed">{q.advantage}</td>
