                            <RechartsTooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                            <Area type="stepAfter" dataKey="price" stroke="#2563eb" strokeWidth={2} fillOpacity={1} fill="url(#colorPrice)" />
                        </AreaChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-900 mb-4">当前排名</h3>
                <div className="space-y-3">
                    {(selectedProject?.quotes || []).sort((a,b) => a.price - b.price).map((q, i) => (
                        <div key={i} className={`p-3 rounded-xl border flex justify-between items-center ${i === 0 ? 'bg-green-50 border-green-200' : 'bg-slate-50 border-slate-100'}`}>
                            <div className="flex items-center gap-3">
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${i === 0 ? 'bg-green-500 text-white' : 'bg-slate-200 text-slate-500'}`}>
                                    {i + 1}
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-slate-900">{q.supplier}</p>
                                    <p className="text-[10px] text-slate-500">{q.delivery}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className={`text-sm font-bold ${i === 0 ? 'text-green-700' : 'text-slate-600'}`}>¥{q.price.toLocaleString()}</p>
