                >
                    模拟供应商出价 (Demo)
                </button>
            </div>
        </div>
      </div>
    );
  };

  // --- Main Render ---

  if (selectedProject) {
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-4">
            <button onClick={() => setSelectedProject(null)} className="p-2 hover:bg-slate-100 rounded-xl transition-colors">
              <ChevronRight className="rotate-180" size={24} />
            </button>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-bold text-slate-900">{selectedProject.title}</h1>
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold border ${getStatusBadgeClass(selectedProject.status)}`}>
                  {selectedProject.status}
                </span>
              </div>
              <p className="text-sm text-slate-500 mt-1">
                项目编号：{selectedProject.id} · 
                方式：{selectedProject.method === ProcurementMethod.BIDDING ? '公开竞价 (Bidding)' : '询比价 (Inquiry)'}
              </p>
            </div>
          </div>
          <div className="flex gap-3">
            {selectedProject.status === ApprovalStatus.DRAFT && (
               <button 
                 onClick={() => handleSubmitForApproval(selectedProject)}
                 className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 flex items-center gap-2"
               >
                 <Send size={18} /> 提交审批
               </button>
            )}

            {selectedProject.status === ApprovalStatus.PENDING && (
               <div className="flex gap-2">
                 <button 
                   onClick={() => handleRejectProject(selectedProject)}
                   className="px-4 py-2 border border-red-200 text-red-600 rounded-xl font-bold hover:bg-red-50"
                 >
                   驳回
                 </button>
                 <button 
                   onClick={() => handleApproveProject(selectedProject)}
                   className="px-6 py-2 bg-green-600 text-white rounded-xl font-bold hover:bg-green-700 shadow-lg shadow-green-200 flex items-center gap-2"
                 >
                   <CheckCircle2 size={18} /> 通过审批
                 </button>
               </div>
            )}

            {selectedProject.status === ApprovalStatus.APPROVED && (
              <>
                {selectedProject.method === ProcurementMethod.INQUIRY && (
                    <button 
                      onClick={() => setIsQuoteModalOpen(true)}
                      className="px-4 py-2 border border-slate-200 rounded-xl font-bold text-slate-600 hover:bg-slate-50 flex items-center gap-2"
                    >
                      <Plus size={18} /> 录入报价
                    </button>
                )}
                {/* For Bidding, quotes are usually entered via supplier portal, but we allow manual override here */}
                <button 
                  onClick={handleGeneratePO}
                  className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200"
                >
                  生成采购订单 (PO)
                </button>
              </>
