        {/* View Switcher based on Method */}
        {selectedProject.method === ProcurementMethod.INQUIRY ? renderInquiryView() : renderBiddingView()}

        {/* Common Project Tracking & AI (Only for Inquiry mainly) */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
             <div className="lg:col-span-2 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
              <h3 className="font-black text-slate-900 mb-6 flex items-center gap-2">
                <UserCheck size={20} className="text-green-600" />
                项目全生命周期追踪
              </h3>
              <div className="relative pl-8 space-y-8">
                <div className="absolute left-3.5 top-2 bottom-2 w-px bg-slate-100"></div>
                {[
                  { step: '发起立项申请', user: '系统管理员', time: selectedProject.createTime, status: 'done' },
                  { step: '部门经理审核', user: '王建国', time: '---', status: selectedProject.status !== ApprovalStatus.DRAFT ? 'done' : 'pending' },
                  { step: '采购中心执行', user: '您', time: '---', status: selectedProject.status === ApprovalStatus.APPROVED ? 'active' : 'pending' },
