import React, { useState, useEffect, useRef } from 'react';
import { 
  ShoppingCart, FilePlus, Gavel, Search, CheckCircle2, Clock, 
  AlertCircle, ShoppingBag, Plus, Filter, ArrowRight, UserCheck, 
  FileText, TrendingDown, DollarSign, Package, Eye, ChevronRight,
  Sparkles, Loader2, X, Send, Timer, Zap, Scale, History
} from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer } from 'recharts';
import { ProcurementMethod, ApprovalStatus } from '../types';
import { evaluateQuotations } from '../services/geminiService';

interface ProcurementExecutionProps {
  initialTab?: string;
}

// Extended Project Interface
interface Project {
  id: string;
  title: string;
  method: ProcurementMethod;
  status: ApprovalStatus;
  budget: number;
  deadline: string;
  createTime: string;
  quotesCount: number;

  // Specific Configs
  inquiryConfig?: {
    inviteCount: number;
    round: number; // Current negotiation round
  };
  bidConfig?: {
    startPrice: number; // Ceiling price
    minStep: number;    // Minimum decrement
    duration: number;   // Minutes
    extensionRule: number; // Extension minutes if bid in last X mins
    startTime?: string;
  };

  // Data
  workflow?: { step: string; user: string; time: string; status: 'done' | 'active' | 'pending' }[];
  quotes?: Quote[]; 
  biddingHistory?: { time: string; price: number; supplier: string }[]; // For chart
}

interface Quote {
  supplier: string;
  price: number;
  delivery: string;
  quality: string;
  advantage: string;
  isWinner?: boolean;
  rank?: number; // For bidding
  paymentTerms?: string; // Critical for inquiry
}

const ProcurementExecution: React.FC<ProcurementExecutionProps> = ({ initialTab = 'projects' }) => {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isQuoteModalOpen, setIsQuoteModalOpen] = useState(false);

  // Simulation State for Bidding
  const [timeLeft, setTimeLeft] = useState(1800); // Seconds
  const [isLive, setIsLive] = useState(false);

  // Form States
  const [newProjectForm, setNewProjectForm] = useState({
    title: '',
    budget: '',
    deadline: '',
    method: ProcurementMethod.INQUIRY,
    // Bidding specific
    startPrice: '',
    minStep: '500',
    duration: '30',
    // Inquiry specific
    inviteCount: '3'
  });

  const [newQuoteForm, setNewQuoteForm] = useState({
    supplier: '',
    price: '',
    delivery: '',
    advantage: ''
  });

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab]);

  // Mock Data Initialization
  const [projects, setProjects] = useState<Project[]>([
    { 
      id: 'PR-2023001', 
      title: '2023年Q4办公室物料集中采购', 
      method: ProcurementMethod.INQUIRY, 
      status: ApprovalStatus.APPROVED, 
      budget: 150000, 
      deadline: '2023-11-30', 
      createTime: '2023-10-15', 
      quotesCount: 3,
      inquiryConfig: { inviteCount: 3, round: 1 },
      quotes: [
        { supplier: '晨光科力普', price: 142000, delivery: '3天', quality: '优', advantage: '长期合作伙伴，售后无忧', paymentTerms: '月结30天' },
        { supplier: '齐心文具', price: 138000, delivery: '5天', quality: '良', advantage: '价格最低，库存充足', paymentTerms: '货到付款' },
        { supplier: '办公伙伴', price: 145000, delivery: '2天', quality: '优', advantage: '送货上门，响应最快', paymentTerms: '月结60天' },
      ]
    },
    { 
      id: 'PR-2023002', 
      title: '服务器扩容硬件招标项目', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.APPROVED, 
      budget: 850000, 
      deadline: '2023-11-15', 
      createTime: '2023-10-20', 
      quotesCount: 4,
      bidConfig: { startPrice: 850000, minStep: 1000, duration: 30, extensionRule: 2 },
      quotes: [
        { supplier: '戴尔(中国)', price: 820000, delivery: '15天', quality: '优', advantage: '原厂直供', rank: 2 },
        { supplier: '浪潮信息', price: 795000, delivery: '7天', quality: '优', advantage: '国产化适配好', rank: 1 },
      ],
      biddingHistory: [
        { time: '10:00', price: 850000, supplier: 'System Start' },
        { time: '10:05', price: 845000, supplier: '联想集团' },
        { time: '10:12', price: 830000, supplier: '戴尔(中国)' },
        { time: '10:15', price: 820000, supplier: '浪潮信息' },
        { time: '10:22', price: 815000, supplier: '联想集团' },
        { time: '10:28', price: 795000, supplier: '浪潮信息' },
      ]
    },
    { 
      id: 'PR-2023003', 
      title: '营销中心礼品定制(竞价)', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.DRAFT, 
      budget: 50000, 
      deadline: '2023-10-25', 
      createTime: '2023-10-22', 
      quotesCount: 0,
      bidConfig: { startPrice: 50000, minStep: 100, duration: 20, extensionRule: 2 },
      quotes: []
    },
  ]);

  // --- Actions ---

  const handleCreateProject = () => {
    if (!newProjectForm.title || !newProjectForm.budget) return;

    const isBidding = newProjectForm.method === ProcurementMethod.BIDDING;

    const newProject: Project = {
      id: `PR-${new Date().getFullYear()}${String(projects.length + 1).padStart(3, '0')}`,
      title: newProjectForm.title,
      method: newProjectForm.method,
      status: ApprovalStatus.DRAFT,
      budget: Number(newProjectForm.budget),
      deadline: newProjectForm.deadline,
      createTime: new Date().toISOString().split('T')[0],
      quotesCount: 0,
      quotes: [],
      // Conditional Config
      bidConfig: isBidding ? {
        startPrice: Number(newProjectForm.startPrice || newProjectForm.budget),
        minStep: Number(newProjectForm.minStep),
        duration: Number(newProjectForm.duration),
        extensionRule: 2
      } : undefined,
      inquiryConfig: !isBidding ? {
        inviteCount: Number(newProjectForm.inviteCount),
        round: 1
      } : undefined
    };

    setProjects([newProject, ...projects]);
    setIsCreateModalOpen(false);
    // Reset form...
    alert('项目创建成功！当前状态：草稿');
  };

  const handleSubmitForApproval = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.PENDING);
    alert('已提交审批流程，等待管理层审核。');
  };

  const handleApproveProject = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.APPROVED);
    alert('审批通过！项目已立项，可以开始邀请供应商报价。');
  };

  const handleRejectProject = (project: Project) => {
    updateProjectStatus(project.id, ApprovalStatus.REJECTED);
  };

  const updateProjectStatus = (id: string, status: ApprovalStatus) => {
    const updated = projects.map(p => p.id === id ? { ...p, status } : p);
    setProjects(updated);
    if (selectedProject?.id === id) setSelectedProject({ ...selectedProject!, status });
  };

  const handleAddQuote = () => {
    if (!selectedProject) return;
    const newQuote: Quote = {
      supplier: newQuoteForm.supplier,
      price: Number(newQuoteForm.price),
      delivery: newQuoteForm.delivery,
      quality: '未知',
      advantage: newQuoteForm.advantage,
      paymentTerms: '月结30天' 
    };

    // If bidding, calculate rank
    let updatedQuotes = [...(selectedProject.quotes || []), newQuote];
    if (selectedProject.method === ProcurementMethod.BIDDING) {
      updatedQuotes.sort((a, b) => a.price - b.price);
      updatedQuotes = updatedQuotes.map((q, idx) => ({ ...q, rank: idx + 1 }));
    }

    const updatedProject = {
      ...selectedProject,
      quotesCount: updatedQuotes.length,
      quotes: updatedQuotes
    };

    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
    setIsQuoteModalOpen(false);
    setNewQuoteForm({ supplier: '', price: '', delivery: '', advantage: '' });
  };

  const handleGeneratePO = () => {
    const winner = selectedProject?.quotes?.find(q => q.isWinner) || selectedProject?.quotes?.[0]; // Default to first if none selected
    alert(`采购订单 (PO) 已生成！\n\n项目：${selectedProject?.title}\n供应商：${winner?.supplier}\n金额：¥${winner?.price}\n状态：已推送至供应商协同端`);
  };

  const handleAwardSupplier = (supplierName: string) => {
    if (!selectedProject) return;
    const updatedQuotes = selectedProject.quotes?.map(q => ({
        ...q,
        isWinner: q.supplier === supplierName
    }));
    const updatedProject = { ...selectedProject, quotes: updatedQuotes };
    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
  };

  const handleOpenProject = async (project: Project) => {
    setSelectedProject(project);
    // Determine AI context based on method
    if (project.status === ApprovalStatus.APPROVED && (project.quotes?.length || 0) > 0) {
      // Only auto-analyze for inquiry, Bidding needs manual trigger or end of auction
      if (project.method === ProcurementMethod.INQUIRY) {
        setIsEvaluating(true);
