      title: newProjectForm.title,
      method: newProjectForm.method,
      status: ApprovalStatus.DRAFT,
      budget: Number(newProjectForm.budget),
      deadline: newProjectForm.deadline,
      createTime: new Date().toISOString().split('T')[0],
      quotesCount: 0,
      quotes: [],
      demandDetails: {
        itemName: newProjectForm.itemName,
        spec: newProjectForm.spec,
        quantity: Number(newProjectForm.quantity),
        unit: newProjectForm.unit,
        deliveryLocation: newProjectForm.deliveryLocation
      },
      approvalChain: Number(newProjectForm.budget) > 500000 
