  const handleStartAuction = () => {
    if (!selectedProject) return;
    const updated = {
        ...selectedProject,
        bidConfig: { ...selectedProject.bidConfig!, auctionStatus: 'active' as const }
    };
    setSelectedProject(updated);
    setProjects(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  const handleStopAuction = () => {
    if (!selectedProject) return;
    const updated = {
        ...selectedProject,
        bidConfig: { ...selectedProject.bidConfig!, auctionStatus: 'completed' as const, timeLeftSeconds: 0 }
    };
    setSelectedProject(updated);
    setProjects(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  const handleSimulateIncomingBid = () => {
    if (!selectedProject || selectedProject.bidConfig?.auctionStatus !== 'active') return;

    // Simulate a random supplier bidding lower
    const currentLowest = selectedProject.quotes?.reduce((min, q) => q.totalTco < min ? q.totalTco : min, selectedProject.bidConfig.startPrice);
    const minStep = selectedProject.bidConfig.minStep || 100;

    // Create new lower price (randomly between 1x and 3x minStep)
    const reduction = minStep * (Math.floor(Math.random() * 3) + 1);
    const newPrice = (currentLowest || 0) - reduction;

    const randomSuppliers = selectedProject.invitedSuppliers?.map(s => s.name) || ['Supplier A', 'Supplier B'];
    const randomSupplier = randomSuppliers[Math.floor(Math.random() * randomSuppliers.length)];

    const newBid: Quote = {
        supplier: randomSupplier,
        unitPrice: newPrice, // Simplified for demo
        taxRate: 13,
        freight: 0, 
        otherCosts: 0,
        totalTco: newPrice,
        delivery: '7天',
        quality: '优',
        advantage: '最新出价',
        quoteTime: new Date().toLocaleTimeString(),
        rank: 1 // Will be resorted
    };

    // Update Project Quotes & History
    const updatedQuotes = [...(selectedProject.quotes || []), newBid]
        .sort((a, b) => a.totalTco - b.totalTco)
        .map((q, i) => ({ ...q, rank: i + 1 }));

    const updatedHistory = [...(selectedProject.biddingHistory || []), {
        time: new Date().toLocaleTimeString('en-US', {hour12: false}),
        price: newPrice,
        supplier: randomSupplier
    }];

    // Anti-Sniping Logic: Check if within last 2 minutes (120s)
    let timeLeft = selectedProject.bidConfig.timeLeftSeconds || 0;
    const extensionRule = selectedProject.bidConfig.extensionRule || 2;
    if (timeLeft < 120) {
        timeLeft += (extensionRule * 60); // Extend
        alert(`触发延时机制！因最后2分钟有新出价，竞价时长自动延长 ${extensionRule} 分钟。`);
    }

    const updatedProject = {
        ...selectedProject,
        bidConfig: { ...selectedProject.bidConfig!, timeLeftSeconds: timeLeft },
        quotes: updatedQuotes,
        biddingHistory: updatedHistory,
        quotesCount: updatedQuotes.length
    };

    setSelectedProject(updatedProject);
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

