import React, { useState, useEffect, useRef } from 'react';
import { 
  ShoppingCart, FilePlus, Gavel, Search, CheckCircle2, Clock, 
  AlertCircle, ShoppingBag, Plus, Filter, ArrowRight, UserCheck, 
  FileText, TrendingDown, DollarSign, Package, Eye, ChevronRight,
  Sparkles, Loader2, X, Send, Timer, Zap, Scale, History, Truck, Receipt, 
  Play, Square, Users, Trophy, AlertTriangle
} from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer } from 'recharts';
import { ProcurementMethod, ApprovalStatus } from '../types';
import { evaluateQuotations } from '../services/geminiService';

interface ProcurementExecutionProps {
  initialTab?: string;
}

// --- Extended Data Models ---

interface DemandDetail {
  itemName: string;
  spec: string;
  quantity: number;
  unit: string;
  deliveryLocation: string;
}

interface Quote {
  supplier: string;
  unitPrice: number; // Excl. Tax
  taxRate: number;   // e.g., 13%
  freight: number;
  otherCosts: number;
  totalTco: number;  // Calculated
  delivery: string;
  quality: string;
  advantage: string;
  isWinner?: boolean;
  rank?: number; // For bidding
  paymentTerms?: string;
  quoteTime: string;
}

interface Project {
  id: string;
  title: string;
  method: ProcurementMethod;
  status: ApprovalStatus;
  budget: number;
  deadline: string;
  createTime: string;
  quotesCount: number;

  // Demand Info
  demandDetails?: DemandDetail;

  // Specific Configs
  inquiryConfig?: {
    inviteCount: number;
    rfqStatus: 'draft' | 'published' | 'closed';
    round: number; 
  };
  bidConfig?: {
    startPrice: number;
    minStep: number;   
    duration: number;  // Minutes
    extensionRule: number; // Minutes
    startTime?: string;
    auctionStatus: 'preparation' | 'active' | 'completed'; // New status for bidding flow
    timeLeftSeconds?: number;
  };

  // Data
  invitedSuppliers?: { name: string; status: 'pending' | 'accepted' }[];
  approvalChain?: { role: string; name: string; status: 'pending' | 'approved' | 'rejected'; time?: string }[];
  quotes?: Quote[]; 
  biddingHistory?: { time: string; price: number; supplier: string }[];
}

const ProcurementExecution: React.FC<ProcurementExecutionProps> = ({ initialTab = 'projects' }) => {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isQuoteModalOpen, setIsQuoteModalOpen] = useState(false);

  // Timer Ref
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Form States
  const [newProjectForm, setNewProjectForm] = useState({
    title: '',
    budget: '',
    deadline: '',
    method: ProcurementMethod.INQUIRY,
    // Demand
    itemName: '',
    spec: '',
    quantity: '1',
    unit: '批',
    deliveryLocation: '公司总仓',
    // Bidding specific
    startPrice: '',
    minStep: '500',
    duration: '30',
    // Inquiry specific
    inviteCount: '3'
  });

  const [newQuoteForm, setNewQuoteForm] = useState({
    supplier: '',
    unitPrice: '',
    taxRate: '13',
    freight: '0',
    otherCosts: '0',
    delivery: '',
    paymentTerms: '',
    advantage: ''
  });

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab]);

  // Clean up timer on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // Timer Logic for Active Auction
  useEffect(() => {
    if (selectedProject?.bidConfig?.auctionStatus === 'active') {
      if (timerRef.current) clearInterval(timerRef.current);

      timerRef.current = setInterval(() => {
        setSelectedProject(prev => {
          if (!prev || !prev.bidConfig || prev.bidConfig.auctionStatus !== 'active') return prev;

          const newTimeLeft = (prev.bidConfig.timeLeftSeconds || 0) - 1;

          if (newTimeLeft <= 0) {
            clearInterval(timerRef.current!);
            return {
              ...prev,
              bidConfig: { ...prev.bidConfig, auctionStatus: 'completed', timeLeftSeconds: 0 }
            };
          }

          return {
            ...prev,
            bidConfig: { ...prev.bidConfig, timeLeftSeconds: newTimeLeft }
          };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
  }, [selectedProject?.bidConfig?.auctionStatus]);


  // Mock Data Initialization
  const [projects, setProjects] = useState<Project[]>([
    { 
      id: 'PR-2023001', 
      title: '2023年Q4办公室物料集中采购', 
      method: ProcurementMethod.INQUIRY, 
      status: ApprovalStatus.APPROVED, 
      budget: 150000, 
      deadline: '2023-11-30', 
      createTime: '2023-10-15', 
      quotesCount: 3,
      demandDetails: {
        itemName: '办公耗材套件',
        spec: '含打印纸、墨盒、文件夹等标准品',
        quantity: 1,
        unit: '批',
        deliveryLocation: '总部行政库'
      },
      inquiryConfig: { inviteCount: 3, round: 1, rfqStatus: 'closed' },
      quotes: [
        { supplier: '晨光科力普', unitPrice: 125000, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 141250, delivery: '3天', quality: '优', advantage: '长期合作伙伴', paymentTerms: '月结30天', quoteTime: '2023-10-16' },
        { supplier: '齐心文具', unitPrice: 120000, taxRate: 13, freight: 500, otherCosts: 0, totalTco: 136100, delivery: '5天', quality: '良', advantage: '价格最低', paymentTerms: '货到付款', quoteTime: '2023-10-17' },
        { supplier: '办公伙伴', unitPrice: 128000, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 144640, delivery: '2天', quality: '优', advantage: '响应最快', paymentTerms: '月结60天', quoteTime: '2023-10-16' },
      ],
      approvalChain: [
        { role: '采购经理', name: '张经理', status: 'approved', time: '2023-10-20' },
        { role: '财务总监', name: '李总监', status: 'pending' }
      ]
    },
    { 
      id: 'PR-2023002', 
      title: '服务器扩容硬件招标项目', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.APPROVED, 
      budget: 850000, 
      deadline: '2023-11-15', 
      createTime: '2023-10-20', 
      quotesCount: 4,
      demandDetails: {
        itemName: '高性能机架式服务器',
        spec: 'CPU: 64核, RAM: 512G, SSD: 8TB',
        quantity: 10,
        unit: '台',
        deliveryLocation: '数据中心机房'
      },
      invitedSuppliers: [
        { name: '戴尔(中国)', status: 'accepted' },
        { name: '浪潮信息', status: 'accepted' },
        { name: '联想集团', status: 'accepted' },
        { name: '紫光股份', status: 'pending' },
      ],
      bidConfig: { 
        startPrice: 850000, 
        minStep: 1000, 
        duration: 30, 
        extensionRule: 2, 
        auctionStatus: 'active',
        timeLeftSeconds: 845 // 14 mins left
      },
      quotes: [
        { supplier: '戴尔(中国)', unitPrice: 82000, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 820000, delivery: '15天', quality: '优', advantage: '原厂直供', rank: 2, quoteTime: '10:12' },
        { supplier: '浪潮信息', unitPrice: 79500, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 795000, delivery: '7天', quality: '优', advantage: '国产化适配', rank: 1, quoteTime: '10:28' },
      ],
      biddingHistory: [
        { time: '10:00', price: 850000, supplier: 'Start' },
        { time: '10:05', price: 845000, supplier: '联想集团' },
        { time: '10:12', price: 830000, supplier: '戴尔(中国)' },
        { time: '10:15', price: 820000, supplier: '浪潮信息' },
        { time: '10:22', price: 815000, supplier: '联想集团' },
        { time: '10:28', price: 795000, supplier: '浪潮信息' },
      ]
    }
  ]);

  // --- Actions ---

  const handleCreateProject = () => {
    if (!newProjectForm.title || !newProjectForm.budget) return;

    const isBidding = newProjectForm.method === ProcurementMethod.BIDDING;

    const newProject: Project = {
      id: `PR-${new Date().getFullYear()}${String(projects.length + 1).padStart(3, '0')}`,
      title: newProjectForm.title,
      method: newProjectForm.method,
      status: ApprovalStatus.DRAFT,
      budget: Number(newProjectForm.budget),
      deadline: newProjectForm.deadline,
      createTime: new Date().toISOString().split('T')[0],
      quotesCount: 0,
      quotes: [],
      demandDetails: {
        itemName: newProjectForm.itemName,
        spec: newProjectForm.spec,
        quantity: Number(newProjectForm.quantity),
        unit: newProjectForm.unit,
        deliveryLocation: newProjectForm.deliveryLocation
      },
      approvalChain: Number(newProjectForm.budget) > 500000 
        ? [{ role: '采购经理', name: '张经理', status: 'pending' }, { role: '总经理', name: '王总', status: 'pending' }]
        : [{ role: '采购经理', name: '张经理', status: 'pending' }],
      // Conditional Config
      bidConfig: isBidding ? {
        startPrice: Number(newProjectForm.startPrice || newProjectForm.budget),
        minStep: Number(newProjectForm.minStep),
        duration: Number(newProjectForm.duration),
        extensionRule: 2,
        auctionStatus: 'preparation',
        timeLeftSeconds: Number(newProjectForm.duration) * 60
      } : undefined,
      inquiryConfig: !isBidding ? {
        inviteCount: Number(newProjectForm.inviteCount),
        round: 1,
        rfqStatus: 'draft'
      } : undefined,
      invitedSuppliers: []
    };

    setProjects([newProject, ...projects]);
    setIsCreateModalOpen(false);
    alert('需求确认成功！项目已创建。');
  };

  const handlePublishRFQ = () => {
    if (!selectedProject) return;
    const updated = { 
        ...selectedProject, 
        status: ApprovalStatus.PENDING,
        inquiryConfig: { ...selectedProject.inquiryConfig!, rfqStatus: 'published' as const } 
    };
    setProjects(projects.map(p => p.id === selectedProject.id ? updated : p));
    setSelectedProject(updated);
    alert('询价单(RFQ)已发送至供应商门户！');
  };

  const handleApproveProject = (project: Project) => {
    const updated = { ...project, status: ApprovalStatus.APPROVED };
    setProjects(projects.map(p => p.id === project.id ? updated : p));
    if (selectedProject?.id === project.id) setSelectedProject(updated);
  };

  const handleAddQuote = () => {
    if (!selectedProject || !selectedProject.demandDetails) return;

    // TCO Calculation
    const unitPrice = Number(newQuoteForm.unitPrice);
    const taxRate = Number(newQuoteForm.taxRate) / 100;
    const freight = Number(newQuoteForm.freight);
    const otherCosts = Number(newQuoteForm.otherCosts);
    const qty = selectedProject.demandDetails.quantity;

    // Total TCO = (Unit * Qty * (1+Tax)) + Freight + Others
    const totalTco = (unitPrice * qty * (1 + taxRate)) + freight + otherCosts;

    const newQuote: Quote = {
      supplier: newQuoteForm.supplier,
      unitPrice,
      taxRate: Number(newQuoteForm.taxRate),
      freight,
      otherCosts,
      totalTco,
      delivery: newQuoteForm.delivery,
      paymentTerms: newQuoteForm.paymentTerms,
      quality: '待评',
      advantage: newQuoteForm.advantage,
      quoteTime: new Date().toISOString().split('T')[0]
    };

    let updatedQuotes = [...(selectedProject.quotes || []), newQuote];

    // Sort logic
    if (selectedProject.method === ProcurementMethod.BIDDING) {
      updatedQuotes.sort((a, b) => a.totalTco - b.totalTco);
      updatedQuotes = updatedQuotes.map((q, idx) => ({ ...q, rank: idx + 1 }));
    } else {
       // For Inquiry, emphasize highlighting best price but don't reorder aggressively immediately
    }

    const updatedProject = {
      ...selectedProject,
      quotesCount: updatedQuotes.length,
      quotes: updatedQuotes
    };

    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
    setIsQuoteModalOpen(false);
    // Reset form
    setNewQuoteForm({
        supplier: '', unitPrice: '', taxRate: '13', freight: '0', otherCosts: '0', 
        delivery: '', paymentTerms: '', advantage: ''
    });
  };

  const handleGeneratePO = () => {
    const winner = selectedProject?.quotes?.find(q => q.isWinner) || selectedProject?.quotes?.[0];
    if (!winner) return alert("请先决标（选定供应商）");
    alert(`采购订单 (PO) 已生成！\n\n关联项目：${selectedProject?.title}\n供应商：${winner.supplier}\n含税总额：¥${winner.totalTco.toLocaleString()}\n\n已同步至「合同管理」模块。`);
  };

  const handleAwardSupplier = (supplierName: string) => {
    if (!selectedProject) return;
    const updatedQuotes = selectedProject.quotes?.map(q => ({
        ...q,
        isWinner: q.supplier === supplierName
    }));
    const updatedProject = { ...selectedProject, quotes: updatedQuotes };
    setProjects(projects.map(p => p.id === selectedProject.id ? updatedProject : p));
    setSelectedProject(updatedProject);
  };

  const handleOpenProject = async (project: Project) => {
    setSelectedProject(project);
    if (project.method === ProcurementMethod.INQUIRY && project.quotes && project.quotes.length > 0) {
        setIsEvaluating(true);
        try {
          // Pass enriched quote data to AI
          const analysis = await evaluateQuotations(project.title, project.quotes);
          setAiAnalysis(analysis);
        } catch (err) {
          setAiAnalysis(null);
        } finally {
          setIsEvaluating(false);
        }
    } else {
      setAiAnalysis(null);
