      quotes: [
        { supplier: '晨光科力普', unitPrice: 125000, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 141250, delivery: '3天', quality: '优', advantage: '长期合作伙伴', paymentTerms: '月结30天', quoteTime: '2023-10-16' },
        { supplier: '齐心文具', unitPrice: 120000, taxRate: 13, freight: 500, otherCosts: 0, totalTco: 136100, delivery: '5天', quality: '良', advantage: '价格最低', paymentTerms: '货到付款', quoteTime: '2023-10-17' },
        { supplier: '办公伙伴', unitPrice: 128000, taxRate: 13, freight: 0, otherCosts: 0, totalTco: 144640, delivery: '2天', quality: '优', advantage: '响应最快', paymentTerms: '月结60天', quoteTime: '2023-10-16' },
      ],
      approvalChain: [
        { role: '采购经理', name: '张经理', status: 'approved', time: '2023-10-20' },
        { role: '财务总监', name: '李总监', status: 'pending' }
      ]
    },
    { 
      id: 'PR-2023002', 
      title: '服务器扩容硬件招标项目', 
      method: ProcurementMethod.BIDDING, 
      status: ApprovalStatus.APPROVED, 
      budget: 850000, 
      deadline: '2023-11-15', 
