      case ApprovalStatus.PENDING: return 'bg-blue-50 text-blue-700 border-blue-100';
      case ApprovalStatus.REJECTED: return 'bg-red-50 text-red-700 border-red-100';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
