                      )}
                    </div>
                  </td>
                  <td className="px-4 py-4 text-right font-mono text-slate-500">¥{q.unitPrice.toLocaleString()}</td>
                  <td className="px-4 py-4 text-right font-mono text-slate-500">{q.taxRate}%</td>
                  <td className="px-4 py-4 text-right font-mono text-slate-500">{q.freight > 0 ? `¥${q.freight}` : '-'}</td>
                  <td className="px-4 py-4 text-right font-mono font-bold text-blue-700 bg-blue-50/30">¥{q.totalTco.toLocaleString()}</td>
