              <h5 className="text-[10px] font-black text-green-400 uppercase mb-3">核心优势 (Pros)</h5>
              <ul className="space-y-2">{aiRecommendation.pros.map((p, i) => <li key={i} className="text-xs text-slate-300 flex items-center gap-2"><div className="w-1 h-1 bg-green-400 rounded-full"></div>{p}</li>)}</ul>
            </div>
            <div className="p-5 bg-white/5 rounded-2xl border border-white/10">
              <h5 className="text-[10px] font-black text-red-400 uppercase mb-3">风险提示 (Cons)</h5>
              <ul className="space-y-2">{aiRecommendation.cons.map((c, i) => <li key={i} className="text-xs text-slate-300 flex items-center gap-2"><div className="w-1 h-1 bg-red-400 rounded-full"></div>{c}</li>)}</ul>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

