          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">{selectedProject.title}</h1>
              <span className="px-2 py-0.5 rounded-full text-xs font-bold border bg-blue-50 text-blue-700 border-blue-100">
