            </div>
          </div>
        </section>

        <div className="pt-8 border-t flex justify-end">
          <button onClick={() => updateInquiryStep(InquiryStep.INVITE)} className="bg-blue-600 text-white px-10 py-3 rounded-2xl font-black shadow-lg shadow-blue-200 flex items-center gap-2 hover:bg-blue-700 transition-all group">
            保存并下一步 <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
