import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, MapPin, Star, ShieldCheck, Plus, Filter, Globe, ExternalLink, 
  Sparkles, Loader2, AlertCircle, Info, CheckCircle2, XCircle, Clock, 
  ChevronRight, FileText, UserCheck, ShieldAlert, ShoppingBag, Upload,
  ArrowUpDown, ChevronsUpDown, Settings2, X, Eye, EyeOff, Trash2, Save,
  Building2, Users, LayoutGrid, ArrowRight
} from 'lucide-react';
import { SupplierStatus, ApprovalStatus } from '../types';
import { smartSourcingAssistant, SourcingResult, analyzeSupplierRisk } from '../services/geminiService';

interface SupplierManagementProps {
  initialTab?: string;
}

interface TableColumn {
  id: string;
  label: string;
  visible: boolean;
  isSystem: boolean;
  key: string;
}

const DEFAULT_COLUMNS: TableColumn[] = [
  { id: 'name', label: '供应商全称', visible: true, isSystem: true, key: 'name' },
  { id: 'tier', label: '供应商分类', visible: true, isSystem: true, key: 'tier' },
  { id: 'category', label: '核心品类', visible: true, isSystem: true, key: 'category' },
  { id: 'location', label: '所在地', visible: true, isSystem: true, key: 'location' },
  { id: 'status', label: '状态', visible: true, isSystem: true, key: 'status' },
  { id: 'score', label: '综合评分', visible: true, isSystem: true, key: 'score' },
];

const SupplierManagement: React.FC<SupplierManagementProps> = ({ initialTab = 'list' }) => {
  const [activeSubTab, setActiveSubTab] = useState(initialTab);
  const [sourcingSource, setSourcingSource] = useState<'nationwide' | 'platform' | 'owned'>('nationwide');
  const [searchCategory, setSearchCategory] = useState('');
  const [isSourcing, setIsSourcing] = useState(false);
  const [sourcingResult, setSourcingResult] = useState<SourcingResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Column Config State
  const [columns, setColumns] = useState<TableColumn[]>([]);
  const [isColModalOpen, setIsColModalOpen] = useState(false);
  const [newColLabel, setNewColLabel] = useState('');

  // Batch Import State & Refs
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImporting, setIsImporting] = useState(false);

  // Filter & Sort State
  const [tierFilter, setTierFilter] = useState('全部');
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(null);

  // Suppliers data with support for custom fields
  const [suppliers, setSuppliers] = useState<any[]>([
    { id: '1', name: '上海宏达工业有限公司', category: '工业五金', status: SupplierStatus.QUALIFIED, score: 92, location: '上海市', tier: '战略合作', customFields: {} },
    { id: '2', name: '深圳飞迅电子', category: '电子元器件', status: SupplierStatus.VERIFIED, score: 85, location: '深圳市', tier: '重点供应', customFields: {} },
    { id: '3', name: '浙江大华工贸', category: '劳保用品', status: SupplierStatus.POTENTIAL, score: 78, location: '杭州市', tier: '潜在供应商', customFields: {} },
    { id: '4', name: '北京联合物流', category: '第三方物流', status: SupplierStatus.QUALIFIED, score: 95, location: '北京市', tier: '战略合作', customFields: {} },
  ]);

  // Load Column Config from LocalStorage
  useEffect(() => {
    const savedCols = localStorage.getItem('srm_supplier_columns');
    if (savedCols) {
      try {
        setColumns(JSON.parse(savedCols));
      } catch (e) {
        setColumns(DEFAULT_COLUMNS);
      }
    } else {
      setColumns(DEFAULT_COLUMNS);
    }
  }, []);

  // Save Column Config
  useEffect(() => {
    if (columns.length > 0) {
      localStorage.setItem('srm_supplier_columns', JSON.stringify(columns));
    }
  }, [columns]);

  useEffect(() => {
    setActiveSubTab(initialTab);
  }, [initialTab]);

  const [selectedRequest, setSelectedRequest] = useState<any>(null);
  const [isAnalyzingRisk, setIsAnalyzingRisk] = useState(false);
  const [aiRiskReport, setAiRiskReport] = useState<string | null>(null);

  const onboardingRequests = [
    { id: 'REQ-001', name: '苏州精控自动化', category: '机械零部件', time: '2023-10-24 10:30', step: '初审', creditScore: 88, status: ApprovalStatus.PENDING },
    { id: 'REQ-002', name: '广州盛达物流', category: '仓储运输', time: '2023-10-24 14:15', step: '现场考察', creditScore: 72, status: ApprovalStatus.PENDING },
    { id: 'REQ-003', name: '武汉恒远化工', category: '基础化工', time: '2023-10-23 09:00', step: '终审', creditScore: 94, status: ApprovalStatus.PENDING },
  ];

  // Column Actions
  const toggleColumnVisibility = (id: string) => {
    setColumns(prev => prev.map(col => col.id === id ? { ...col, visible: !col.visible } : col));
  };

  const addCustomColumn = () => {
    if (!newColLabel.trim()) return;
    const newCol: TableColumn = {
      id: `custom_${Date.now()}`,
      label: newColLabel,
      visible: true,
      isSystem: false,
      key: `custom_${newColLabel}`
    };
    setColumns([...columns, newCol]);
    setNewColLabel('');
  };

  const removeCustomColumn = (id: string) => {
    setColumns(prev => prev.filter(col => col.id !== id));
  };

  const handleStartSourcing = async () => {
    if (!searchCategory.trim()) return;
    setIsSourcing(true);
    setError(null);
    setSourcingResult(null);

    try {
      if (sourcingSource === 'nationwide') {
        const result = await smartSourcingAssistant(searchCategory);
        setSourcingResult(result);
      } else if (sourcingSource === 'platform') {
        // Simulate Platform Search
        setTimeout(() => {
          setSourcingResult({
            suppliers: [
              { name: `智采认证-${searchCategory}-A厂`, creditRating: 'AAA', matchScore: 98, platform: '平台优选', advantage: '平台认证金牌商家', potentialRisk: '暂无' },
              { name: `智采认证-${searchCategory}-B科技`, creditRating: 'AA+', matchScore: 92, platform: '平台入驻', advantage: '响应速度快', potentialRisk: '产能饱和风险' },
              { name: `智采认证-${searchCategory}-C贸易`, creditRating: 'AA', matchScore: 88, platform: '平台入驻', advantage: '价格极具竞争力', potentialRisk: '物流配送一般' },
            ],
            strategicAdvice: '平台供应商已通过实名认证与基础验厂，交易安全性高，建议优先通过平台发起询价。'
          });
          setIsSourcing(false);
        }, 1500);
        return; // Early return as we handled state update in timeout
      } else {
        // Simulate Owned Suppliers Search
        setTimeout(() => {
           const ownedResults = suppliers.filter(s => s.category.includes(searchCategory) || s.name.includes(searchCategory));
           // If no direct match in mock data, return dummy owned data
           const results = ownedResults.length > 0 ? ownedResults.map(s => ({
             name: s.name,
             creditRating: '已入库',
             matchScore: 100,
             platform: '自有库',
             advantage: `${s.tier}，历史合作评分${s.score}`,
             potentialRisk: '需关注合同续签'
           })) : [
             { name: `自有库-${searchCategory}-老王工业`, creditRating: '合格', matchScore: 100, platform: '自有库', advantage: '长期合作，价格优惠', potentialRisk: '单一依赖' },
             { name: `自有库-${searchCategory}-新锐制造`, creditRating: '考察中', matchScore: 85, platform: '自有库', advantage: '技术创新能力强', potentialRisk: '处于考察期' }
           ];

           setSourcingResult({
             suppliers: results,
             strategicAdvice: '自有库供应商配合度高且已建立信任关系，可直接一键发起询价。'
           });
           setIsSourcing(false);
        }, 1000);
        return;
      }
    } catch (err: any) {
      setError(err.message || '寻源过程中出现错误');
    } finally {
      if (sourcingSource === 'nationwide') {
        setIsSourcing(false);
      }
    }
  };

  const handleReviewRequest = async (request: any) => {
    setSelectedRequest(request);
    setIsAnalyzingRisk(true);
    setAiRiskReport(null);
    try {
      const report = await analyzeSupplierRisk(request.name);
      setAiRiskReport(report);
    } catch (err) {
      setAiRiskReport("由于系统繁忙，AI风险评估暂时无法生成。");
    } finally {
      setIsAnalyzingRisk(false);
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (!text) return;
      setTimeout(() => {
        const lines = text.split(/\r\n|\n/);
        const newSuppliers = lines
          .slice(1)
          .filter(line => line.trim() !== '')
          .map((line, index) => {
            const cols = line.split(',');
            return {
              id: `IMP-${Date.now()}-${index}`,
              name: cols[0]?.trim() || '未命名导入供应商',
              category: cols[1]?.trim() || '通用物资',
              status: SupplierStatus.POTENTIAL,
              score: 60,
              location: cols[2]?.trim() || '未知',
              tier: '潜在供应商',
              customFields: {}
            };
          });
        if (newSuppliers.length > 0) {
          setSuppliers(prev => [...newSuppliers, ...prev]); 
          alert(`成功导入 ${newSuppliers.length} 条供应商数据`);
        }
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 1000);
    };
    reader.readAsText(file);
  };

  const handleSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const processedSuppliers = [...suppliers]
    .filter(s => tierFilter === '全部' || s.tier === tierFilter)
    .sort((a, b) => {
      if (!sortConfig) return 0;
      const valA = a[sortConfig.key] || a.customFields?.[sortConfig.key] || '';
      const valB = b[sortConfig.key] || b.customFields?.[sortConfig.key] || '';
      if (typeof valA === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
      }
      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });

  const getStatusStyle = (status: SupplierStatus) => {
    switch (status) {
      case SupplierStatus.QUALIFIED: return 'bg-green-100 text-green-700';
      case SupplierStatus.VERIFIED: return 'bg-blue-100 text-blue-700';
      case SupplierStatus.POTENTIAL: return 'bg-amber-100 text-amber-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getTierBadgeStyle = (tier: string) => {
    switch (tier) {
      case '战略合作': return 'bg-purple-100 text-purple-700 border-purple-200';
      case '重点供应': return 'bg-indigo-50 text-indigo-700 border-indigo-100';
      case '一般供应': return 'bg-slate-50 text-slate-600 border-slate-200';
      case '潜在供应商': return 'bg-amber-50 text-amber-600 border-amber-100';
      default: return 'bg-slate-50 text-slate-600';
    }
  };

  // Helper to render cell value based on column config
  const renderCell = (supplier: any, col: TableColumn) => {
    if (col.id === 'name') {
      return (
        <div className="flex items-center gap-2">
          <span className="font-bold text-slate-900">{supplier.name}</span>
          {supplier.score > 90 && <ShieldCheck size={16} className="text-blue-500" />}
        </div>
      );
    }
    if (col.id === 'tier') {
      return (
        <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-tight border ${getTierBadgeStyle(supplier.tier)}`}>
          {supplier.tier}
        </span>
      );
    }
    if (col.id === 'status') {
      return (
        <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-tight ${getStatusStyle(supplier.status)}`}>
          {supplier.status}
        </span>
      );
    }
    if (col.id === 'score') {
      return (
        <div className="flex items-center gap-1">
          <Star size={14} className="text-amber-400 fill-amber-400" />
          <span className="text-sm font-black text-slate-700">{supplier.score}</span>
        </div>
      );
    }
    if (col.id === 'location') {
      return (
        <div className="flex items-center gap-1 text-slate-600">
          <MapPin size={14} className="text-slate-400" />
          {supplier.location}
        </div>
      );
    }

    // Default or Custom Field
    const val = supplier[col.key] || supplier.customFields?.[col.key] || '-';
    return <span className="text-sm text-slate-600 font-medium">{val}</span>;
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">供应商管理中心</h1>
          <div className="flex gap-4 mt-2">
            {[
              { id: 'list', label: '供应商库' },
              { id: 'sourcing', label: '智能寻源' },
              { id: 'onboarding', label: '准入审批' },
              { id: 'eval', label: '绩效考核' },
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveSubTab(tab.id)}
                className={`text-sm font-bold pb-1 border-b-2 transition-all ${activeSubTab === tab.id ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>
        <button className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-xl hover:bg-blue-700 transition-all font-bold shadow-lg shadow-blue-200">
          <Plus size={18} />
          邀请新商入驻
        </button>
      </div>

      {activeSubTab === 'list' && (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex gap-4 bg-slate-50/50">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" placeholder="搜索供应商名称、品类、主营物资、信用标签..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm" />
            </div>

            <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".csv" className="hidden" />

            <button onClick={handleImportClick} disabled={isImporting} className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-white hover:text-blue-600 transition-colors">
              {isImporting ? <Loader2 size={18} className="animate-spin" /> : <Upload size={18} />}
              批量导入
            </button>

            <div className="relative group">
               <select value={tierFilter} onChange={(e) => setTierFilter(e.target.value)} className="appearance-none bg-white border border-slate-200 text-slate-600 text-sm font-bold rounded-xl px-4 py-2.5 pr-10 hover:border-blue-400 outline-none cursor-pointer transition-colors">
                 <option value="全部">全部分级</option>
                 <option value="战略合作">战略合作</option>
                 <option value="重点供应">重点供应</option>
                 <option value="一般供应">一般供应</option>
                 <option value="潜在供应商">潜在供应商</option>
               </select>
               <ChevronsUpDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            <button 
