              <Settings2 size={18} />
              显示列配置
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead className="bg-slate-50 border-b border-slate-100 text-left">
                <tr>
                  {columns.filter(c => c.visible).map(col => (
                    <th 
                      key={col.id}
                      className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase tracking-wider cursor-pointer hover:text-blue-600 hover:bg-slate-100 transition-colors whitespace-nowrap"
                      onClick={() => handleSort(col.key)}
                    >
                      <div className="flex items-center gap-1">
                        {col.label}
                        <ArrowUpDown size={12} className={sortConfig?.key === col.key ? 'text-blue-600' : 'text-slate-300'} />
                      </div>
                    </th>
                  ))}
                  <th className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase tracking-wider text-right">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {processedSuppliers.map((s) => (
                  <tr key={s.id} className="hover:bg-slate-50/80 transition-colors">
                    {columns.filter(c => c.visible).map(col => (
                      <td key={col.id} className="px-6 py-4">
                        {renderCell(s, col)}
                      </td>
                    ))}
                    <td className="px-6 py-4 text-right">
                      <button className="text-blue-600 hover:text-blue-800 text-sm font-bold">查看档案</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {processedSuppliers.length === 0 && (
            <div className="py-20 text-center text-slate-400 font-medium">未找到符合筛选条件的供应商</div>
          )}
        </div>
      )}

      {/* Column Config Modal */}
      {isColModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-end bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-300">
           <div className="w-[400px] h-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right-4 duration-500">
              <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                 <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-blue-200">
                       <Settings2 size={20} />
                    </div>
                    <div>
                       <h3 className="font-black text-slate-900 leading-none">列显示配置</h3>
                       <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest mt-1">Column Customization</p>
                    </div>
                 </div>
                 <button onClick={() => setIsColModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-lg transition-colors">
                    <X size={20} className="text-slate-400" />
                 </button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-8">
                 <section className="space-y-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <div className="w-1 h-1 bg-blue-600 rounded-full"></div> 常用显示列
                    </h4>
                    <div className="space-y-2">
                       {columns.filter(c => c.isSystem).map(col => (
                          <div 
                             key={col.id} 
                             onClick={() => toggleColumnVisibility(col.id)}
                             className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${col.visible ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-slate-50 border-slate-100 text-slate-400 opacity-60'}`}
                          >
                             <span className="text-sm font-bold">{col.label}</span>
                             {col.visible ? <Eye size={18} /> : <EyeOff size={18} />}
                          </div>
                       ))}
                    </div>
                 </section>

                 <section className="space-y-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <div className="w-1 h-1 bg-blue-600 rounded-full"></div> 自定义动态列
                    </h4>
                    <div className="space-y-2 mb-4">
                       {columns.filter(c => !c.isSystem).map(col => (
                          <div key={col.id} className="flex items-center gap-2">
                             <div 
                                onClick={() => toggleColumnVisibility(col.id)}
                                className={`flex-1 flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${col.visible ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-slate-50 border-slate-100 text-slate-400 opacity-60'}`}
                             >
                                <span className="text-sm font-bold">{col.label}</span>
                                {col.visible ? <Eye size={18} /> : <EyeOff size={18} />}
                             </div>
                             <button 
                                onClick={() => removeCustomColumn(col.id)}
                                className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                             >
                                <Trash2 size={18} />
                             </button>
                          </div>
                       ))}
                       {columns.filter(c => !c.isSystem).length === 0 && (
                          <p className="text-xs text-slate-400 italic py-2">暂无自定义列，可在下方新增</p>
                       )}
                    </div>

                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200">
                       <p className="text-xs font-bold text-slate-700 mb-2">新增自定义字段</p>
                       <div className="flex gap-2">
                          <input 
                             type="text" 
                             value={newColLabel}
                             onChange={(e) => setNewColLabel(e.target.value)}
                             placeholder="如：财务编号、联系电话" 
                             className="flex-1 px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none focus:ring-2 focus:ring-blue-500"
                          />
                          <button 
                             onClick={addCustomColumn}
                             className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 transition-colors"
                          >
                             <Plus size={18} />
                          </button>
                       </div>
                    </div>
                 </section>
              </div>

              <div className="p-6 border-t border-slate-100 bg-slate-50">
                 <button 
                    onClick={() => setIsColModalOpen(false)}
                    className="w-full flex items-center justify-center gap-2 py-3 bg-slate-900 text-white rounded-xl font-bold shadow-xl shadow-slate-900/10 hover:bg-slate-800 transition-all"
                 >
                    <Save size={18} />
                    保存并应用配置
                 </button>
                 <p className="text-[10px] text-slate-400 text-center mt-3">配置将自动保存并同步至您的个人设置</p>
              </div>
           </div>
        </div>
      )}

      {activeSubTab === 'sourcing' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
              <div className="flex flex-col gap-4">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">
                      <Sparkles className="text-blue-600" size={24} />
                      AI 智能寻源助理
                    </h3>
                    <p className="text-sm text-slate-500 mt-1">
                      {sourcingSource === 'nationwide' ? '深度聚合企查查、1688 等全球供应商库数据' : 
                       sourcingSource === 'platform' ? '搜索平台已认证的优质供应商' : '在自有供应商库中快速筛选'}
                    </p>
                  </div>
                  <span className="text-[10px] font-black px-2 py-1 bg-blue-50 text-blue-600 rounded-lg flex items-center gap-1 border border-blue-100">
                    <Globe size={12} />
                    {sourcingSource === 'nationwide' ? 'GLOBAL DATA' : sourcingSource === 'platform' ? 'PLATFORM DATA' : 'PRIVATE DATA'}
                  </span>
                </div>

                {/* Source Selection Tabs */}
                <div className="flex p-1 bg-slate-100 rounded-xl w-fit">
                  <button 
                    onClick={() => { setSourcingSource('nationwide'); setSourcingResult(null); setSearchCategory(''); }}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${sourcingSource === 'nationwide' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <Globe size={14} /> 全国供应商
                  </button>
                  <button 
                    onClick={() => { setSourcingSource('platform'); setSourcingResult(null); setSearchCategory(''); }}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${sourcingSource === 'platform' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <LayoutGrid size={14} /> 平台供应商
                  </button>
                  <button 
                    onClick={() => { setSourcingSource('owned'); setSourcingResult(null); setSearchCategory(''); }}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${sourcingSource === 'owned' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <Building2 size={14} /> 自有供应商
                  </button>
                </div>
              </div>

              <div className="flex gap-3">
                <div className="relative flex-1">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                  <input 
                    type="text" 
                    value={searchCategory}
                    onChange={(e) => setSearchCategory(e.target.value)}
                    placeholder={
                      sourcingSource === 'nationwide' ? "请输入物资名称或类别，如：不锈钢精密无缝管" :
                      sourcingSource === 'platform' ? "搜索平台供应商名称或主营业务" : "搜索自有供应商库..."
                    }
                    className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all font-medium" 
                  />
                </div>
                <button 
                  onClick={handleStartSourcing}
                  disabled={isSourcing || !searchCategory}
                  className="bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all disabled:opacity-50 flex items-center gap-2 font-bold shadow-lg shadow-blue-200"
                >
                  {isSourcing ? <Loader2 className="animate-spin" size={20} /> : <Search size={20} />}
                  开始寻源
                </button>
              </div>

              {isSourcing && (
                <div className="py-20 flex flex-col items-center justify-center text-slate-400 gap-6">
                  <div className="relative">
                    <Loader2 className="animate-spin text-blue-600" size={48} strokeWidth={3} />
                    <Sparkles size={20} className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-blue-400 animate-pulse" />
                  </div>
                  <div className="text-center">
                    <p className="text-slate-900 font-black text-lg">正在搜索{sourcingSource === 'nationwide' ? '全网' : sourcingSource === 'platform' ? '平台' : '自有'}数据...</p>
                    <p className="text-sm mt-1 text-slate-500">正在调取信用评级与经营风险指数</p>
                  </div>
                </div>
              )}

              {sourcingResult && !isSourcing && (
                <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {sourcingResult.suppliers.map((s, i) => (
                      <div key={i} className="p-5 bg-white border border-slate-200 rounded-3xl shadow-sm hover:border-blue-400 hover:shadow-xl hover:shadow-blue-500/5 transition-all group">
                        <div className="flex justify-between items-start mb-4">
                          <h5 className="font-black text-slate-900 group-hover:text-blue-600 transition-colors text-lg leading-tight">{s.name}</h5>
                          <span className="text-[10px] font-black px-2 py-0.5 bg-slate-100 text-slate-500 rounded uppercase tracking-tighter">{s.platform}</span>
                        </div>
                        <div className="flex items-center gap-4 mb-4">
                          <div className="bg-green-50 px-2 py-1 rounded-lg">
                            <span className="text-[10px] text-green-600 font-bold block leading-none">信用评级</span>
                            <span className="text-sm font-black text-green-700">{s.creditRating}</span>
                          </div>
                          <div className="bg-blue-50 px-2 py-1 rounded-lg">
                            <span className="text-[10px] text-blue-600 font-bold block leading-none">匹配指数</span>
                            <span className="text-sm font-black text-blue-700">{s.matchScore}%</span>
                          </div>
