                        { step: '实地考察评价', user: '现场采集端', time: '10-24 11:20', status: 'completed' },
                        { step: '准入最终决策', user: '您', time: '等待处理', status: 'pending' },
                      ].map((s, i) => (
                        <div key={i} className="flex gap-5 relative z-10">
                          <div className={`w-1.5 h-1.5 rounded-full mt-2 ring-4 ring-white ${s.status === 'completed' ? 'bg-green-500' : 'bg-blue-600 animate-pulse'}`}></div>
                          <div>
                            <p className="text-sm font-bold text-slate-900">{s.step}</p>
                            <p className="text-[10px] text-slate-500 font-medium">{s.user} · {s.time}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <hr className="border-slate-100" />

                  <div className="space-y-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
