                      <div className="w-1.5 h-1.5 bg-blue-600 rounded-full"></div> 智能工作流
                    </h4>
                    <div className="space-y-6 relative pl-3">
                      <div className="absolute left-3 top-2 bottom-2 w-px bg-slate-100"></div>
                      {[
                        { step: '合规性初审', user: 'AI Assistant', time: '10-24 10:35', status: 'completed' },
                        { step: '实地考察评价', user: '现场采集端', time: '10-24 11:20', status: 'completed' },
