import React, { useState } from 'react';
import { 
  FileText, Plus, Search, Filter, ArrowRight, BrainCircuit, Sparkles, 
  CheckCircle2, AlertTriangle, XCircle, ChevronRight, Layers, FileInput, 
  FileCog, Archive, Users, Building2, Zap, Loader2, ClipboardList
} from 'lucide-react';
import { 
  analyzeProcurementNeeds, 
  generatePlanStrategy, 
  auditApproval 
} from '../services/geminiService';

interface ProjectManagementProps {
  initialTab?: string;
}

const ProjectManagement: React.FC<ProjectManagementProps> = ({ initialTab = 'needs' }) => {
  const [activeSubTab, setActiveSubTab] = useState(initialTab);

  // State for Needs
  const [needs, setNeeds] = useState([
    { id: 'REQ-HR-001', dept: '人力资源部', item: 'A4纸、黑色签字笔', category: '办公用品', qty: 50, budget: 2000, date: '2023-10-25', status: '待处理', risk: null },
    { id: 'REQ-IT-002', dept: 'IT部', item: '戴尔显示器 24寸', category: 'IT设备', qty: 10, budget: 12000, date: '2023-10-26', status: '待处理', risk: null },
    { id: 'REQ-MFG-003', dept: '生产部', item: '劳保手套、防护眼镜', category: 'MRO', qty: 500, budget: 5000, date: '2023-10-26', status: '待处理', risk: null },
    { id: 'REQ-ADM-004', dept: '行政部', item: '打印纸、文件夹', category: '办公用品', qty: 100, budget: 4000, date: '2023-10-27', status: '待处理', risk: null },
  ]);
  const [selectedNeeds, setSelectedNeeds] = useState<string[]>([]);
  const [needsAnalysis, setNeedsAnalysis] = useState<any>(null);
  const [isAnalyzingNeeds, setIsAnalyzingNeeds] = useState(false);

  // State for Plans
  const [plans, setPlans] = useState([
    { id: 'PLAN-2023-001', title: 'Q4季度办公用品集中采购', budget: 6000, items: ['REQ-HR-001', 'REQ-ADM-004'], status: '方案制定中', strategy: null, approval: null },
  ]);
  const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
  const [isAuditing, setIsAuditing] = useState(false);

  // Handlers
  const toggleNeedSelection = (id: string) => {
    setSelectedNeeds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleMergeNeeds = async () => {
    if (selectedNeeds.length === 0) return;
    setIsAnalyzingNeeds(true);
    const selectedItems = needs.filter(n => selectedNeeds.includes(n.id));
    try {
      const result = await analyzeProcurementNeeds(selectedItems);
      setNeedsAnalysis(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzingNeeds(false);
    }
  };

  const createPlanFromMerge = () => {
    if (!needsAnalysis) return;
    const newPlan = {
      id: `PLAN-2023-${Date.now().toString().slice(-4)}`,
      title: '新建合并采购计划',
      budget: needs.filter(n => selectedNeeds.includes(n.id)).reduce((sum, n) => sum + n.budget, 0),
      items: selectedNeeds,
      status: '方案制定中',
      strategy: null,
      approval: null
    };
    setPlans([newPlan, ...plans]);
    setNeedsAnalysis(null);
    setSelectedNeeds([]);
    setActiveSubTab('plan');
  };

  const handleGenerateStrategy = async (planId: string) => {
    setIsGeneratingPlan(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      // Mocking item details for AI context
      const result = await generatePlanStrategy(plan.items, plan.budget);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, strategy: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsGeneratingPlan(false);
    }
  };

  const handleAudit = async (planId: string) => {
    setIsAuditing(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      const result = await auditApproval('plan', plan);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, approval: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsAuditing(false);
    }
  };

  // --- Views ---

  const renderNeedsView = () => (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="flex justify-between items-center bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
