                    <button className="text-blue-600 hover:bg-blue-50 p-1.5 rounded-lg transition-colors" title="点击进行AI单据合规性检查">
                      <BrainCircuit size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* AI Analysis Panel */}
        {needsAnalysis && (
           <div className="w-80 bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col animate-in slide-in-from-right duration-300">
              <div className="flex items-center gap-3 mb-6">
                 <div className="p-2 bg-purple-600 rounded-xl"><Sparkles size={20} /></div>
                 <h3 className="font-black text-lg">合并建议</h3>
              </div>
              <div className="flex-1 space-y-4 overflow-y-auto">
                 <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                    <p className="text-sm text-slate-300 leading-relaxed mb-3">{needsAnalysis.summary}</p>
                    {needsAnalysis.suggestions?.map((s: any, i: number) => (
                      <div key={i} className="mb-3 last:mb-0">
                         <span className="text-xs font-bold text-purple-400 uppercase">{s.category}</span>
                         <p className="text-xs text-white mt-1">建议合并: {s.items.join(', ')}</p>
                         <p className="text-[10px] text-slate-400 mt-1 italic">"{s.reason}"</p>
                      </div>
                    ))}
                 </div>
              </div>
              <button 
                onClick={createPlanFromMerge}
                className="w-full mt-4 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold transition-colors shadow-lg"
              >
                生成采购方案
              </button>
           </div>
        )}
      </div>
    </div>
  );

  const renderPlanView = () => (
    <div className="space-y-6 animate-in fade-in duration-300">
       <h2 className="text-2xl font-black text-slate-900">采购方案与策略制定</h2>

