             { id: 'PROJ-2023-072', title: '生产线MRO备件包', status: '已归档', date: '2023-08-10', amount: 125000 },
             { id: 'PROJ-2023-065', title: '员工中秋福利采购', status: '已归档', date: '2023-08-01', amount: 88000 },
          ].map((p, i) => (
