             <button onClick={() => setActiveSubTab('needs')} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeSubTab === 'needs' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>采购需求</button>
