                </div>
             </div>
          ))}
       </div>
    </div>
  );

  return (
    <div className="space-y-6">
       {activeSubTab === 'needs' && renderNeedsView()}
       {activeSubTab === 'plan' && (isEditingPlan ? renderPlanForm() : renderPlanList())}
       {activeSubTab === 'archive' && renderArchiveView()}
    </div>
  );
};

