    if (selectedNeeds.length < 2) {
      alert("请至少选择两条采购需求进行智能合并分析");
      return;
    }
    setIsAnalyzingNeeds(true);
    const selectedItems = needs.filter(n => selectedNeeds.includes(n.id));
    try {
      const result = await analyzeProcurementNeeds(selectedItems);
      setNeedsAnalysis(result);
      // Initialize merge selection with all analyzed items by default
      setMergeSelection(selectedNeeds);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzingNeeds(false);
    }
  };

  const toggleMergeItem = (id: string) => {
    setMergeSelection(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

