    if (!needsAnalysis) return;
    // Switch to Plan tab and open Editor mode
    setActiveSubTab('plan');
    setIsEditingPlan(true);
    // Here you would typically pre-fill the form with analysis data, 
    // for now we just reset the analysis state
    setNeedsAnalysis(null);
    setSelectedNeeds([]);
    setMergeSelection([]);
  };

