    setIsGeneratingPlan(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      // Mocking item details for AI context
      const result = await generatePlanStrategy(plan.items, plan.budget);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, strategy: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsGeneratingPlan(false);
    }
  };

  const handleAudit = async (planId: string) => {
    setIsAuditing(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      const result = await auditApproval('plan', plan);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, approval: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsAuditing(false);
    }
