                          <h4 className="text-sm font-black text-slate-800 mb-2 flex items-center gap-2">
                             <BrainCircuit size={16} className="text-blue-500" /> 推荐策略: {plan.strategy.method}
                          </h4>
                          <p className="text-xs text-slate-600 leading-relaxed mb-3">{plan.strategy.reason}</p>
                          <div className="flex flex-wrap gap-2">
                             {plan.strategy.recommendedSuppliers?.map((s: string, i: number) => (
                                <span key={i} className="flex items-center gap-1 px-2 py-1 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-600">
