                       </div>
                       <div className="flex items-center gap-2 text-xs text-amber-600 bg-amber-50 px-3 py-2 rounded-lg">
                          <AlertTriangle size={14} />
                          <span className="font-bold">风险提示:</span> {plan.strategy.riskAssessment}
                       </div>
                    </div>
                 )}
              </div>

              {/* Right: Approval Flow */}
              <div className="p-8 w-full md:w-96 bg-slate-50 flex flex-col">
                 <h4 className="text-sm font-black text-slate-900 mb-6 flex items-center justify-between">
                    <span>审批流程</span>
                    {plan.approval && (
                       <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${
                          plan.approval.status === 'pass' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                       }`}>
                          AI 审计: {plan.approval.status === 'pass' ? '通过' : '预警'}
                       </span>
                    )}
                 </h4>

                 <div className="flex-1 relative pl-4 border-l-2 border-slate-200 space-y-8">
                    {[
                       { role: '部门经理', status: 'approved', time: '10-27 14:30' },
                       { role: '采购总监', status: 'current', time: '处理中' },
                       { role: '财务总监', status: 'pending', time: '-' },
                       { role: '总经理', status: 'pending', time: '-' },
                    ].map((step, i) => (
                       <div key={i} className="relative">
                          <div className={`absolute -left-[21px] top-1 w-3 h-3 rounded-full ring-4 ring-slate-50 ${
                             step.status === 'approved' ? 'bg-green-500' : 
                             step.status === 'current' ? 'bg-blue-600 animate-pulse' : 'bg-slate-300'
                          }`}></div>
                          <p className={`text-sm font-bold ${step.status === 'current' ? 'text-blue-600' : 'text-slate-900'}`}>{step.role}</p>
                          <p className="text-xs text-slate-400">{step.time}</p>
                       </div>
                    ))}
                 </div>

                 {!plan.approval ? (
                    <button 
                       onClick={() => handleAudit(plan.id)}
                       disabled={!plan.strategy || isAuditing}
                       className="mt-6 w-full py-3 border border-slate-200 bg-white text-slate-600 hover:text-blue-600 hover:border-blue-200 rounded-xl font-bold transition-all flex items-center justify-center gap-2"
                    >
                       {isAuditing ? <Loader2 className="animate-spin" size={16} /> : <ShieldCheck size={16} />}
                       启动 AI 辅助审批
                    </button>
                 ) : (
                    <div className="mt-6 p-3 bg-white border border-slate-200 rounded-xl">
                       <p className="text-xs font-bold text-slate-900 mb-1">AI 审核意见 ({plan.approval.confidence}%)</p>
                       <p className="text-[10px] text-slate-500 leading-relaxed">{plan.approval.comment}</p>
                       <div className="mt-3 flex gap-2">
                          <button className="flex-1 py-1.5 bg-green-50 text-green-700 rounded-lg text-xs font-bold hover:bg-green-100">通过</button>
                          <button className="flex-1 py-1.5 bg-red-50 text-red-700 rounded-lg text-xs font-bold hover:bg-red-100">驳回</button>
                       </div>
                    </div>
                 )}
              </div>
           </div>
         ))}
       </div>
    </div>
  );

  return (
    <div className="space-y-6">
       {activeSubTab === 'needs' && renderNeedsView()}
       {activeSubTab === 'plan' && (isEditingPlan ? renderPlanForm() : renderPlanList())}
       {activeSubTab === 'archive' && renderArchiveView()}
    </div>
  );
};

