        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 border-b border-slate-100 text-left">
            <tr>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目编号</th>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目名称</th>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase">归档日期</th>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase">负责人</th>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase text-center">状态</th>
              <th className="px-6 py-4 font-bold text-slate-500 uppercase text-right">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {[
              { id: 'ARC-2023-088', title: '2023上半年IT设备集中采购', date: '2023-07-15', owner: '李明', status: '已归档' },
              { id: 'ARC-2023-042', title: '生产线自动化改造一期', date: '2023-05-20', owner: '王强', status: '已归档' },
              { id: 'ARC-2022-115', title: '年度办公用品框架协议', date: '2022-12-30', owner: '张伟', status: '已归档' },
            ].map((item, i) => (
              <tr key={i} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-mono text-slate-500">{item.id}</td>
                <td className="px-6 py-4 font-bold text-slate-900">{item.title}</td>
                <td className="px-6 py-4 text-slate-600">{item.date}</td>
                <td className="px-6 py-4 text-slate-600 flex items-center gap-2">
                  <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold text-slate-500">
                    {item.owner.charAt(0)}
                  </div>
                  {item.owner}
                </td>
                <td className="px-6 py-4 text-center">
                  <span className="px-2 py-1 bg-slate-100 text-slate-500 rounded text-xs font-bold">{item.status}</span>
                </td>
                <td className="px-6 py-4 text-right">
                  <button className="text-blue-600 hover:underline font-bold text-xs">查看卷宗</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {/* Empty State */}
        <div className="hidden py-20 text-center text-slate-400">
           <Archive size={48} className="mx-auto mb-4 opacity-20" />
           <p>暂无归档项目</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
       {activeSubTab === 'needs' && renderNeedsView()}
       {activeSubTab === 'plan' && (isEditingPlan ? renderPlanForm() : renderPlanList())}
       {activeSubTab === 'archive' && renderArchiveView()}
    </div>
  );
};

export default ProjectManagement;

import React, { useState, useEffect } from 'react';
import { 
  FileText, Plus, Search, Filter, ArrowRight, BrainCircuit, Sparkles, 
  CheckCircle2, AlertTriangle, XCircle, ChevronRight, Layers, FileInput, 
  FileCog, Archive, Users, Building2, Zap, Loader2, ClipboardList, ShieldCheck,
  ChevronLeft, Upload, Trash2, Calendar, Coins, UserCircle, Briefcase
} from 'lucide-react';
import { 
  analyzeProcurementNeeds, 
  generatePlanStrategy, 
  auditApproval 
} from '../services/geminiService';

interface ProjectManagementProps {
  initialTab?: string;
}

const ProjectManagement: React.FC<ProjectManagementProps> = ({ initialTab = 'needs' }) => {
  const [activeSubTab, setActiveSubTab] = useState(initialTab);

  // Sync internal state with prop from Sidebar
  useEffect(() => {
    setActiveSubTab(initialTab);
    // If switching tabs via sidebar, reset editing state
    if (initialTab !== 'plan') {
      setIsEditingPlan(false);
    }
  }, [initialTab]);

  // State for Needs
  const [needs, setNeeds] = useState([
    { id: 'REQ-HR-001', dept: '人力资源部', item: 'A4纸、黑色签字笔', category: '办公用品', qty: 50, budget: 2000, date: '2023-10-25', status: '待处理', risk: null },
    { id: 'REQ-IT-002', dept: 'IT部', item: '戴尔显示器 24寸', category: 'IT设备', qty: 10, budget: 12000, date: '2023-10-26', status: '待处理', risk: null },
    { id: 'REQ-MFG-003', dept: '生产部', item: '劳保手套、防护眼镜', category: 'MRO', qty: 500, budget: 5000, date: '2023-10-26', status: '待处理', risk: null },
    { id: 'REQ-ADM-004', dept: '行政部', item: '打印纸、文件夹', category: '办公用品', qty: 100, budget: 4000, date: '2023-10-27', status: '待处理', risk: null },
  ]);
  const [selectedNeeds, setSelectedNeeds] = useState<string[]>([]);
  const [needsAnalysis, setNeedsAnalysis] = useState<any>(null);
  const [isAnalyzingNeeds, setIsAnalyzingNeeds] = useState(false);

  // State for merge adjustments
  const [mergeSelection, setMergeSelection] = useState<string[]>([]);

  // State for Plans
  const [plans, setPlans] = useState([
    { id: 'PLAN-2023-001', title: 'Q4季度办公用品集中采购', budget: 6000, items: ['REQ-HR-001', 'REQ-ADM-004'], status: '方案制定中', strategy: null, approval: null },
  ]);
  const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
  const [isAuditing, setIsAuditing] = useState(false);
  const [isEditingPlan, setIsEditingPlan] = useState(false);

  // Handlers
  const toggleNeedSelection = (id: string) => {
    setSelectedNeeds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleMergeNeeds = async () => {
    if (selectedNeeds.length < 2) {
      alert("请至少选择两条采购需求进行智能合并分析");
      return;
    }
    setIsAnalyzingNeeds(true);
    const selectedItems = needs.filter(n => selectedNeeds.includes(n.id));
    try {
      const result = await analyzeProcurementNeeds(selectedItems);
      setNeedsAnalysis(result);
      // Initialize merge selection with all analyzed items by default
      setMergeSelection(selectedNeeds);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzingNeeds(false);
    }
  };

  const toggleMergeItem = (id: string) => {
    setMergeSelection(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const createPlanFromMerge = () => {
    if (!needsAnalysis) return;
    // Switch to Plan tab and open Editor mode
    setActiveSubTab('plan');
    setIsEditingPlan(true);
    // Here you would typically pre-fill the form with analysis data, 
    // for now we just reset the analysis state
    setNeedsAnalysis(null);
    setSelectedNeeds([]);
    setMergeSelection([]);
  };

  const handleGenerateStrategy = async (planId: string) => {
    setIsGeneratingPlan(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      // Mocking item details for AI context
      const result = await generatePlanStrategy(plan.items, plan.budget);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, strategy: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsGeneratingPlan(false);
    }
  };

  const handleAudit = async (planId: string) => {
    setIsAuditing(true);
    const plan = plans.find(p => p.id === planId);
    if (!plan) return;

    try {
      const result = await auditApproval('plan', plan);
      setPlans(prev => prev.map(p => p.id === planId ? { ...p, approval: result } : p));
    } catch (e) {
      console.error(e);
    } finally {
      setIsAuditing(false);
    }
  };

  // --- Views ---

  const renderNeedsView = () => (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="flex justify-between items-center bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-xl font-black text-slate-900">部门采购需求汇总</h2>
          <p className="text-sm text-slate-500 mt-1">HR、IT、生产及行政部门提交的待处理需求池</p>
        </div>
        <div className="flex gap-3">
           <button 
             onClick={handleMergeNeeds}
             disabled={isAnalyzingNeeds}
             className="flex items-center gap-2 bg-purple-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-purple-700 transition-all shadow-lg shadow-purple-200"
           >
             {isAnalyzingNeeds ? <Loader2 className="animate-spin" size={18} /> : <Layers size={18} />}
             智能辅助合并
           </button>
           <button className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-xl font-bold hover:bg-slate-800 transition-all">
             <Plus size={18} /> 新增需求
           </button>
        </div>
      </div>

      <div className="flex gap-6">
        <div className="flex-1 bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden h-fit">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 border-b border-slate-100 text-left">
              <tr>
                <th className="px-6 py-4 w-12"><input type="checkbox" className="rounded text-blue-600" /></th>
                <th className="px-6 py-4 font-bold text-slate-500 uppercase">单号 / 部门</th>
                <th className="px-6 py-4 font-bold text-slate-500 uppercase">物资内容</th>
                <th className="px-6 py-4 font-bold text-slate-500 uppercase">类别</th>
                <th className="px-6 py-4 font-bold text-slate-500 uppercase text-right">预估预算</th>
                <th className="px-6 py-4 font-bold text-slate-500 uppercase text-center">AI 预审</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {needs.map(n => (
                <tr key={n.id} className={`hover:bg-slate-50 transition-colors ${selectedNeeds.includes(n.id) ? 'bg-blue-50/30' : ''}`}>
                  <td className="px-6 py-4">
                    <input 
                      type="checkbox" 
                      checked={selectedNeeds.includes(n.id)} 
                      onChange={() => toggleNeedSelection(n.id)}
                      className="rounded text-blue-600 focus:ring-blue-500 cursor-pointer" 
                    />
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{n.dept}</div>
                    <div className="text-xs text-slate-400 font-mono">{n.id}</div>
                  </td>
                  <td className="px-6 py-4 font-medium text-slate-700">{n.item} <span className="text-slate-400">x{n.qty}</span></td>
                  <td className="px-6 py-4"><span className="px-2 py-1 bg-slate-100 rounded text-xs font-bold text-slate-600">{n.category}</span></td>
                  <td className="px-6 py-4 text-right font-mono font-bold text-slate-900">¥{n.budget.toLocaleString()}</td>
                  <td className="px-6 py-4 text-center">
                    <button className="text-blue-600 hover:bg-blue-50 p-1.5 rounded-lg transition-colors" title="点击进行AI单据合规性检查">
                      <BrainCircuit size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* AI Analysis Panel - Interactive */}
        {needsAnalysis && (
           <div className="w-96 bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col animate-in slide-in-from-right duration-300 h-fit sticky top-6">
              <div className="flex items-center justify-between mb-6">
                 <div className="flex items-center gap-3">
                    <div className="p-2 bg-purple-600 rounded-xl"><Sparkles size={20} /></div>
                    <h3 className="font-black text-lg">智能合并建议</h3>
                 </div>
                 <button onClick={() => setNeedsAnalysis(null)} className="text-slate-400 hover:text-white"><XCircle size={20} /></button>
              </div>

              <div className="p-4 bg-white/10 rounded-2xl border border-white/10 mb-6">
                 <p className="text-sm text-slate-300 leading-relaxed font-medium">"{needsAnalysis.summary}"</p>
              </div>

              <div className="flex-1 space-y-4 overflow-y-auto mb-6">
                 <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">待合并明细 (请勾选确认)</p>
                 <div className="space-y-2">
                    {needs.filter(n => selectedNeeds.includes(n.id)).map(n => (
                       <div key={n.id} className="flex items-start gap-3 p-3 bg-slate-800 rounded-xl border border-slate-700">
                          <input 
                            type="checkbox" 
                            checked={mergeSelection.includes(n.id)}
                            onChange={() => toggleMergeItem(n.id)}
                            className="mt-1 rounded border-slate-600 bg-slate-700 text-purple-600 focus:ring-purple-500" 
                          />
                          <div>
                             <p className="text-sm font-bold text-white">{n.item}</p>
                             <div className="flex gap-2 mt-1 text-[10px] text-slate-400">
                                <span>{n.dept}</span>
                                <span>·</span>
                                <span>¥{n.budget}</span>
                             </div>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>

              <div className="mt-auto">
                <div className="flex justify-between items-center text-sm mb-3 px-1">
                   <span className="text-slate-400">已选合并项</span>
                   <span className="font-bold text-white">{mergeSelection.length} 项</span>
                </div>
                <button 
                  onClick={createPlanFromMerge}
                  disabled={mergeSelection.length === 0}
                  className="w-full py-3 bg-purple-600 hover:bg-purple-500 disabled:bg-slate-700 disabled:text-slate-500 rounded-xl font-bold transition-colors shadow-lg shadow-purple-900/20"
                >
                  确认并生成采购方案
                </button>
              </div>
           </div>
        )}
      </div>
    </div>
