}

enum InquiryStep {
  CREATE = 1,
  INVITE = 2,
  PUBLISH = 3,
  RECEIVE = 4,
  AWARD = 5
}

enum BiddingStep {
  SETUP = 1,
  QUALIFICATION = 2,
  PRE_BID = 3,
  AUCTION = 4,
  DECISION = 5
}

interface ProjectItem {
  name: string;
  spec: string;
  qty: number;
  unit: string;
}

interface Project {
  id: string;
  title: string;
  method: ProcurementMethod;
  status: ApprovalStatus;
  budget: number;
  deadline: string;
  createTime: string;
  quotesCount: number;
  currentStep: number;

  demandDetails?: {
    items: ProjectItem[];
    specialTerms?: string;
  };
  invitedSuppliers?: { name: string; status: 'pending' | 'accepted' | 'declined' | 'viewed'; lastAction?: string }[];
  quotes?: any[];
  bidConfig?: any;
  biddingHistory?: any[];
}

