                 <h3 className="text-lg font-black text-slate-900 flex items-center gap-2 mb-2">
                   <FileText className="text-blue-600" size={20} /> 项目概况
                 </h3>
                 <div className="text-sm text-slate-500 space-y-1">
                    <p><span className="font-bold text-slate-700 mr-2">项目名称:</span> {selectedProject?.title}</p>
                    <p><span className="font-bold text-slate-700 mr-2">项目编号:</span> {selectedProject?.id}</p>
                    <p><span className="font-bold text-slate-700 mr-2">预算金额:</span> ¥{selectedProject?.budget.toLocaleString()}</p>
                 </div>
              </div>
              <div className="text-right">
                 <div className="text-xs font-bold text-slate-400 uppercase mb-1">当前状态</div>
                 <div className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-sm font-black border border-blue-100 inline-block">
                    {biddingSteps.find(s => s.step === selectedProject?.currentStep)?.label}
                 </div>
              </div>
           </div>
        </div>

        {/* Bidding Content Based on Step */}
        {selectedProject?.currentStep === BiddingStep.AUCTION ? (
          <div className="space-y-6">
             <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col justify-between relative overflow-hidden h-64 shadow-2xl">
                <div className="absolute top-0 right-0 p-8 opacity-10"><Timer size={120} /></div>
                <div className="flex items-center gap-3">
                   <span className="w-3 h-3 bg-green-500 rounded-full animate-pulse shadow-lg shadow-green-500/50"></span>
                   <h2 className="text-xl font-black">正在竞价大厅直播中</h2>
                </div>
                <div className="flex items-end justify-between relative z-10">
                   <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">当前最低报价</p>
                      <p className="text-6xl font-black text-blue-400 tracking-tighter">¥1,950,000</p>
                      <p className="text-xs text-slate-500 mt-2">领先供应商: 匿名供应商 B</p>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">剩余时间</p>
                      <p className="text-3xl font-mono font-bold">00:19:42</p>
                      <p className="text-xs text-slate-500 mt-2">共 {selectedProject?.quotesCount} 次出价</p>
                   </div>
                </div>
             </div>

             {/* Live Bid Stream Placeholder */}
             <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm h-64 flex items-center justify-center text-slate-400">
                <div className="text-center">
                   <ActivityStreamIcon />
                   <p className="text-sm font-bold mt-2">实时出价流加载中...</p>
                </div>
             </div>
          </div>
        ) : (
          <div className="bg-white p-20 text-center rounded-[2.5rem] border border-dashed border-slate-200">
             <Settings2 size={48} className="mx-auto text-slate-200 mb-4" />
             <p className="text-slate-400 font-bold">该阶段 ({biddingSteps.find(s => s.step === selectedProject?.currentStep)?.label}) 配置与管理功能开发中</p>
             <button onClick={() => updateStep(BiddingStep.AUCTION)} className="mt-6 text-blue-600 font-bold hover:underline text-sm">
                模拟进入竞价演示
             </button>
          </div>
        )}
      </div>
    );
  };

  const ActivityStreamIcon = () => (
    <svg className="w-12 h-12 mx-auto text-slate-300 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 12h-4l-3 9L9 3l-3 9H2"/>
    </svg>
  );

  // --- MAIN RENDER LOGIC ---

  // Check for Mall Tab First
  if (initialTab === 'mall') {
    return renderMallView();
  }

  // Then check for Selected Project Detail View
  if (selectedProject) {
    const currentStepsConfig = selectedProject.method === ProcurementMethod.INQUIRY ? inquirySteps : biddingSteps;

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-4">
            <button onClick={() => setSelectedProject(null)} className="p-2 hover:bg-slate-100 rounded-xl transition-colors">
              <ArrowLeft size={24} className="text-slate-600" />
            </button>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-black text-slate-900">{selectedProject.title || (selectedProject.method === ProcurementMethod.INQUIRY ? '新询价立项' : '新竞价立项')}</h1>
                <span className="px-2 py-0.5 rounded-full text-[10px] font-black uppercase border bg-blue-50 text-blue-700 border-blue-100">
                  {selectedProject.status}
                </span>
              </div>
              <p className="text-sm text-slate-500 mt-1">项目流水号：{selectedProject.id} · 类型：{selectedProject.method}</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button className="px-6 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-50 transition-all">
              <Download size={18} /> 导出详情
            </button>
          </div>
        </div>

        {/* Unified Stepper for Both Types */}
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm mb-6 overflow-hidden">
          <div className="flex items-center justify-between">
            {currentStepsConfig.map((s, idx) => {
              const Icon = s.icon;
              const isPast = (selectedProject?.currentStep || 0) > s.step;
              const isCurrent = (selectedProject?.currentStep || 0) === s.step;
              return (
                <React.Fragment key={s.step}>
                  <div className="flex flex-col items-center gap-2 flex-1 relative group cursor-pointer" onClick={() => isPast && updateStep(s.step)}>
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-500 ${
                      isCurrent ? 'bg-blue-600 text-white shadow-xl shadow-blue-200 ring-4 ring-blue-50' : 
                      isPast ? 'bg-green-100 text-green-600' : 'bg-slate-50 text-slate-300'
                    }`}>
                      {isPast ? <CheckCircle2 size={24} /> : <Icon size={24} />}
                    </div>
                    <span className={`text-[10px] font-black uppercase tracking-widest mt-2 ${isCurrent ? 'text-blue-600' : 'text-slate-400'}`}>
                      {s.label}
                    </span>
                  </div>
                  {idx < currentStepsConfig.length - 1 && (
                    <div className={`h-0.5 w-16 mx-2 -mt-6 transition-all duration-1000 ${isPast ? 'bg-green-200' : 'bg-slate-100'}`}></div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        {/* RENDER CURRENT STAGE CONTENT */}
        {selectedProject.method === ProcurementMethod.INQUIRY ? (
          <div className="min-h-[600px]">
            {selectedProject.currentStep === InquiryStep.CREATE && renderCreateStage()}
            {selectedProject.currentStep === InquiryStep.INVITE && renderInviteStage()}
            {selectedProject.currentStep === InquiryStep.PUBLISH && renderPublishStage()}
            {selectedProject.currentStep === InquiryStep.RECEIVE && renderReceiveStage()}
            {selectedProject.currentStep === InquiryStep.AWARD && renderAwardStage()}
          </div>
        ) : (
          <div className="min-h-[600px]">
            {/* Reuse create stage or have custom bidding creation if needed, reusing for now */}
            {selectedProject.currentStep === BiddingStep.SETUP && renderCreateStage()}
            {selectedProject.currentStep === BiddingStep.QUALIFICATION && renderInviteStage()}
            {selectedProject.currentStep !== BiddingStep.SETUP && selectedProject.currentStep !== BiddingStep.QUALIFICATION && renderBiddingDetail()}
          </div>
        )}
      </div>
    );
  }

  // --- DEFAULT LIST VIEW ---

  const listProjects = projects.filter(p => p.method === (initialTab === 'inquiry' ? ProcurementMethod.INQUIRY : ProcurementMethod.BIDDING));
  const pageTitle = initialTab === 'inquiry' ? '询比采购' : '竞价采购';

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight">
            {pageTitle}
          </h1>
          <p className="text-sm text-slate-500 mt-1">管理各采购阶段的项目进度与协作</p>
        </div>
        <button 
          onClick={() => {
            setSelectedProject(newProject);
          }} 
          className="flex items-center gap-2 bg-slate-900 text-white px-6 py-2.5 rounded-2xl hover:bg-slate-800 transition-all font-bold shadow-xl shadow-slate-900/10"
        >
          <Plus size={20} />
          发起{initialTab === 'inquiry' ? '询价' : '竞价'}立项
        </button>
      </div>

      {/* UNIFIED TABLE VIEW FOR BOTH INQUIRY AND BIDDING */}
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
           <table className="w-full text-sm">
              <thead className="bg-slate-50 border-b border-slate-100 text-left">
                 <tr>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase w-16 text-center">序号</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目编号</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目名称</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase text-right">预算</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase">截止日期</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目阶段</th>
                    <th className="px-6 py-4 font-bold text-slate-500 uppercase text-center">操作</th>
                 </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                 {listProjects.map((p, index) => {
                    const currentStepLabel = p.method === ProcurementMethod.INQUIRY 
                      ? inquirySteps.find(s => s.step === p.currentStep)?.label 
                      : biddingSteps.find(s => s.step === p.currentStep)?.label;

                    return (
                    <tr key={p.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => handleOpenProject(p)}>
                       <td className="px-6 py-4 text-center font-bold text-slate-400">
                          {index + 1}
                       </td>
                       <td className="px-6 py-4 font-mono text-slate-500 font-bold">
                          {p.id}
                       </td>
                       <td className="px-6 py-4">
                          <p className="font-bold text-slate-900">{p.title}</p>
                       </td>
                       <td className="px-6 py-4 text-right">
                          <span className="font-mono font-bold text-slate-900">¥{p.budget.toLocaleString()}</span>
                       </td>
                       <td className="px-6 py-4 font-medium text-slate-600">
                          {p.deadline}
                       </td>
                       <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                             <span className="text-[10px] font-black px-2 py-0.5 rounded-lg border uppercase bg-blue-50 text-blue-700 border-blue-100">
                               {p.status}
                             </span>
                             <span className="text-[10px] font-black px-2 py-0.5 rounded-lg bg-slate-900 text-white">
                               {currentStepLabel}
                             </span>
                          </div>
                       </td>
                       <td className="px-6 py-4 text-center">
                          <button className="px-3 py-1.5 bg-white border border-slate-200 text-blue-600 rounded-lg text-xs font-bold hover:bg-blue-50 transition-all shadow-sm">
                             查看详情
                          </button>
                       </td>
                    </tr>
                 )})}
                 {listProjects.length === 0 && (
                    <tr>
                       <td colSpan={7} className="py-12 text-center text-slate-400">
                          <Search size={32} className="mx-auto mb-2 opacity-20" />
                          <p>暂无正在进行中的{initialTab === 'inquiry' ? '询价' : '竞价'}项目</p>
                       </td>
                    </tr>
                 )}
              </tbody>
           </table>
      </div>
    </div>
  );
};

