  const [expandedGroups, setExpandedGroups] = useState<string[]>(['srm', 'project', 'procure']);

  const menuGroups: MenuGroup[] = [
    {
      id: 'general',
      label: '基础工作台',
      items: [
        { id: 'dashboard', label: '控制面板', icon: LayoutDashboard },
      ]
    },
    {
      id: 'srm',
      label: '供应商关系 (SRM)',
      items: [
        { id: 'suppliers/sourcing', label: '智能寻源', icon: Sparkles },
