        { id: 'suppliers/onboarding', label: '准入审批', icon: ClipboardCheck },
        { id: 'suppliers/finance', label: '费用管理', icon: Wallet },
      ]
    },
    {
      id: 'project',
      label: '项目管理 (PM)',
      items: [
        { id: 'projects/needs', label: '采购需求', icon: FileInput },
