          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-bold text-xl shadow-lg shadow-blue-500/20">智</div>
          <div className="flex flex-col">
            <span className="text-lg font-bold tracking-tight leading-none">智采云</span>
            <span className="text-[10px] text-blue-400 font-bold uppercase tracking-widest mt-1">Enterprise SRM</span>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-3 space-y-6 pb-6">
          {menuGroups.map((group) => (
            <div key={group.id} className="space-y-1">
              <button 
                onClick={() => toggleGroup(group.id)}
                className="w-full flex items-center justify-between px-3 py-2 text-[11px] font-bold text-slate-500 uppercase tracking-wider hover:text-slate-300 transition-colors"
              >
                {group.label}
                {expandedGroups.includes(group.id) ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
              </button>

              {expandedGroups.includes(group.id) && (
                <div className="space-y-1 animate-in fade-in slide-in-from-top-1 duration-200">
                  {group.items.map((item) => {
                    const Icon = item.icon;
                    const isActive = isTabActive(item.id);
                    return (
                      <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition-all group ${
                          isActive 
                            ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' 
                            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                        }`}
                      >
                        <div className="flex items-center gap-3">
                          <Icon size={18} className={isActive ? 'text-white' : 'text-slate-500 group-hover:text-white transition-colors'} />
                          <span className="text-sm font-medium">{item.label}</span>
                        </div>
                        {item.badge && (
                          <span className={`px-1.5 py-0.5 rounded-md text-[10px] font-bold ${isActive ? 'bg-white text-blue-600' : 'bg-red-50 text-white'}`}>
                            {item.badge}
                          </span>
                        )}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-800 bg-slate-900/50">
          <div className="flex items-center gap-3 px-3 py-2 rounded-xl hover:bg-slate-800 transition-all cursor-pointer">
            <div className="relative">
              <div className="w-10 h-10 rounded-xl bg-slate-700 overflow-hidden">
                <img src="https://picsum.photos/seed/manager/100" alt="Avatar" />
              </div>
              <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-green-500 border-2 border-slate-900 rounded-full"></div>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm text-white font-bold truncate">张经理</p>
              <p className="text-[10px] text-slate-500 uppercase font-bold tracking-tight">采购部总监</p>
            </div>
            <Settings size={16} className="text-slate-500 hover:text-white transition-colors" />
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 sticky top-0 z-10 shadow-sm">
          <div className="flex items-center gap-4 w-96">
            <div className="relative w-full">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="搜索寻源、订单、合同、供应商..." 
                className="w-full bg-slate-50 border border-slate-200 rounded-full py-2 pl-10 pr-4 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none text-slate-700"
              />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-1 px-3 py-1.5 bg-blue-50 rounded-full text-blue-700 text-xs font-bold">
              <Sparkles size={14} />
              AI 助手在线
            </div>
            <button className="relative text-slate-600 hover:text-blue-600 transition-colors">
              <Bell size={20} />
              <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[10px] rounded-full flex items-center justify-center border-2 border-white font-bold">4</span>
            </button>
            <div className="h-8 w-px bg-slate-200"></div>
            <div className="flex items-center gap-2 cursor-pointer hover:bg-slate-50 p-1.5 rounded-lg transition-all">
              <span className="text-sm font-medium text-slate-600">简体中文</span>
              <ChevronDown size={14} className="text-slate-400" />
            </div>
          </div>
        </header>

        {/* Scrollable Area */}
        <div className="flex-1 overflow-y-auto bg-[#f8fafc]">
          <div className="max-w-7xl mx-auto p-8">
            {children}
          </div>
        </div>
      </main>
    </div>
  );
};

export default Layout;

