                     </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderArchiveView = () => {
    if (selectedArchiveId) {
      return renderArchiveDetail();
    }

    return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black text-slate-900">项目档案库</h2>
          <p className="text-sm text-slate-500 mt-1">已归档的历史采购项目与合同文件</p>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input type="text" placeholder="搜索项目编号或名称..." className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm outline-none w-64" />
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
         <table className="w-full text-sm">
            <thead className="bg-slate-50 border-b border-slate-100 text-left">
               <tr>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase w-20 text-center whitespace-nowrap">序号</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目编号</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase">项目名称</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase">归档日期</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase">中标供应商</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase text-right">总金额</th>
                  <th className="px-6 py-4 font-bold text-slate-500 uppercase text-center">操作</th>
               </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
               {archivedProjects.map((archive, index) => (
                  <tr key={archive.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => setSelectedArchiveId(archive.id)}>
                     <td className="px-6 py-4 text-center font-bold text-slate-400 whitespace-nowrap">
                        {index + 1}
                     </td>
                     <td className="px-6 py-4 font-mono text-slate-500 font-bold">
                        {archive.id}
                     </td>
                     <td className="px-6 py-4">
                        <p className="font-bold text-slate-900">{archive.title}</p>
                        <p className="text-xs text-slate-400 mt-0.5">{archive.dept}</p>
                     </td>
                     <td className="px-6 py-4 font-medium text-slate-600">
                        {archive.finishDate}
                     </td>
                     <td className="px-6 py-4 font-medium text-slate-700">
                        {archive.supplier}
                     </td>
                     <td className="px-6 py-4 text-right">
                        <span className="font-mono font-bold text-slate-900">¥{archive.totalAmount.toLocaleString()}</span>
                     </td>
                     <td className="px-6 py-4 text-center">
                        <button className="px-3 py-1.5 bg-white border border-slate-200 text-blue-600 rounded-lg text-xs font-bold hover:bg-blue-50 transition-all shadow-sm">
                           查看详情
                        </button>
                     </td>
                  </tr>
               ))}
            </tbody>
         </table>
      </div>
    </div>
  )};

  return (
    <div className="space-y-6">
       {activeSubTab === 'needs' && renderNeedsView()}
       {activeSubTab === 'plan' && (
         isEditingPlan ? renderCreatePlanForm() : 
         selectedPlanId ? renderPlanDetail() : 
         renderPlanList()
       )}
       {activeSubTab === 'archive' && renderArchiveView()}
    </div>
  );
};

export default ProjectManagement;

